// 🧭 Navigation guide: every formula in the course with explanations, grouped by topic (t = TOPICS index).
// Item: {id, n:[no,en] name, f:[no,en] formula HTML, e:[no,en] explanation HTML, ex?:[no,en] worked example}
const GUIDE = (() => {
const S = s => [s, s];
const SUM = "Σ", y_ = "y<sub>pred</sub>";
return [
// ===== 0 Data & preprocessing =====
{t:0, items:[
 {id:"g-minmax", n:["Min-max-skalering","Min-max scaling"],
  f:["$x' = \\frac{x - \\min}{\\max - \\min}$", "$x' = \\frac{x - \\min}{\\max - \\min}$"],
  e:["Skalerer en feature til [0, 1] (<code>MinMaxScaler</code>). min og max hentes <b>bare fra treningsdataene</b>, og testdata får samme transformasjon. Testverdier utenfor treningsintervallet havner derfor utenfor [0, 1]. Følsom for outliere, fordi de bestemmer min og max.","Scales a feature to [0, 1] (<code>MinMaxScaler</code>). min and max come <b>from the training data only</b>, and test data get the same transform. Test values outside the training range therefore end up outside [0, 1]. Sensitive to outliers, because they set min and max."],
  ex:["<div class=\"gset\">En boligprismodell skalerer boareal. I treningsdataene er minste bolig 50 m² og største 250 m².</div><ol class=\"gsteps\"><li>$\\max - \\min = 250 - 50 = 200$</li><li>Ny leilighet på 90 m²: $x' = \\frac{90 - 50}{200} = 0{,}2$</li><li>Testbolig på 300 m²: $x' = \\frac{300 - 50}{200} = 1{,}25$</li></ol><div class=\"gans\"><b>Svar:</b> 90 m² blir 0,2, mens testboligen på 300 m² havner utenfor [0, 1] fordi min og max bare hentes fra treningsdataene.</div>","<div class=\"gset\">A house-price model scales floor area. In the training set the smallest house is 50 m² and the largest 250 m².</div><ol class=\"gsteps\"><li>$\\max - \\min = 250 - 50 = 200$</li><li>New flat of 90 m²: $x' = \\frac{90 - 50}{200} = 0.2$</li><li>Test house of 300 m²: $x' = \\frac{300 - 50}{200} = 1.25$</li></ol><div class=\"gans\"><b>Answer:</b> 90 m² becomes 0.2, while the 300 m² test house lands outside [0, 1] because min and max come from the training data only.</div>"]},
 {id:"g-zscore", n:["Standardisering (z-score)","Standardisation (z-score)"],
  f:["$z = \\frac{x - \\mu}{\\sigma} \\iff x = \\mu + z\\,\\sigma$", "$z = \\frac{x - \\mu}{\\sigma} \\iff x = \\mu + z\\,\\sigma$"],
  e:["Gir en feature snitt 0 og standardavvik 1 (<code>StandardScaler</code>). μ og σ fra treningsdataene. Del på σ (standardavviket), ikke σ² (variansen). Formelen baklengs (<code>inverse_transform</code>) gir tilbake originalverdien.","Gives a feature mean 0 and standard deviation 1 (<code>StandardScaler</code>). μ and σ from the training data. Divide by σ (the standard deviation), not σ² (the variance). The formula backwards (<code>inverse_transform</code>) gives back the original value."],
  ex:["<div class=\"gset\">Et sykehus standardiserer systolisk blodtrykk. Treningsdata: μ = 120 mmHg, σ = 15 mmHg. En ny pasient har 150 mmHg.</div><ol class=\"gsteps\"><li>$x - \\mu = 150 - 120 = 30$</li><li>$z = \\frac{30}{15} = 2$</li><li>Baklengs for $z = -1$: $x = 120 + (-1) \\cdot 15 = 105$</li></ol><div class=\"gans\"><b>Svar:</b> Pasienten ligger 2 standardavvik over snittet, og z = −1 svarer til 105 mmHg.</div>","<div class=\"gset\">A hospital standardises systolic blood pressure. Training data: μ = 120 mmHg, σ = 15 mmHg. A new patient has 150 mmHg.</div><ol class=\"gsteps\"><li>$x - \\mu = 150 - 120 = 30$</li><li>$z = \\frac{30}{15} = 2$</li><li>Backwards for $z = -1$: $x = 120 + (-1) \\cdot 15 = 105$</li></ol><div class=\"gans\"><b>Answer:</b> The patient is 2 standard deviations above the mean, and z = −1 corresponds to 105 mmHg.</div>"]},
 {id:"g-robust", n:["Robust skalering","Robust scaling"],
  f:["$x' = \\frac{x - \\text{median}}{\\text{IQR}}, \\qquad \\text{IQR} = Q_3 - Q_1$", "$x' = \\frac{x - \\text{median}}{\\text{IQR}}, \\qquad \\text{IQR} = Q_3 - Q_1$"],
  e:["Bruker median og interkvartilbredde, som nesten ikke påvirkes av noen få ekstreme verdier. Velg denne når dataene har outliere. Både min-max og z-score dras av dem.","Uses the median and the interquartile range, which barely change because of a few extreme values. Choose it when the data have outliers. Both min-max and z-score are pulled by them."],
  ex:["<div class=\"gset\">Månedsinntekter for kunder (i tusen) har median 40, Q₁ = 30 og Q₃ = 55, pluss én outlier på 400.</div><ol class=\"gsteps\"><li>$\\text{IQR} = Q_3 - Q_1 = 55 - 30 = 25$</li><li>Vanlig kunde, 60: $x' = \\frac{60 - 40}{25} = 0{,}8$</li><li>Outlier: $x' = \\frac{400 - 40}{25} = 14{,}4$</li></ol><div class=\"gans\"><b>Svar:</b> Vanlige kunder havner nær 0 og outlieren skiller seg ut med 14,4, uten å presse alle andre sammen slik min-max ville gjort.</div>","<div class=\"gset\">Monthly customer incomes (in thousands) have median 40, Q₁ = 30 and Q₃ = 55, plus one outlier at 400.</div><ol class=\"gsteps\"><li>$\\text{IQR} = Q_3 - Q_1 = 55 - 30 = 25$</li><li>Typical customer, 60: $x' = \\frac{60 - 40}{25} = 0.8$</li><li>Outlier: $x' = \\frac{400 - 40}{25} = 14.4$</li></ol><div class=\"gans\"><b>Answer:</b> Ordinary customers stay close to 0 and the outlier sticks out at 14.4, without squeezing everyone else together as min-max would.</div>"]},
 {id:"g-onehot", n:["Antall kolonner etter koding","Number of columns after encoding"],
  f:["One-hot: $k$ kolonner for en nominell feature med $k$ verdier ($k - 1$ med drop-first)<br>Ordinal / label encoding: 1 kolonne · numerisk: 1 kolonne", "One-hot: $k$ columns for a nominal feature with $k$ values ($k - 1$ with drop-first)<br>Ordinal / label encoding: 1 column · numeric: 1 column"],
  e:["Nominelle kategorier (farge, land) har ingen rekkefølge og bør one-hot-kodes. Ordinale (S/M/L) har en naturlig rekkefølge og kan få ett tall hver. Numeriske features beholdes.","Nominal categories (colour, country) have no order and should be one-hot encoded. Ordinal ones (S/M/L) have a natural order and can get one number each. Numeric features are kept."],
  ex:["<div class=\"gset\">Et datasett med bruktbilpriser har farge (5 verdier), drivstoff (bensin/diesel/elektrisk), tilstand (dårlig/ok/god) og tallene kilometerstand og årsmodell.</div><ol class=\"gsteps\"><li>Farge er nominell: one-hot gir $5$ kolonner</li><li>Drivstoff er nominell: $3$ kolonner</li><li>Tilstand er ordinal ($0, 1, 2$): $1$ kolonne; km-stand og årsmodell: $1 + 1$</li><li>Totalt: $5 + 3 + 1 + 2 = 11$; med drop-first: $4 + 2 + 1 + 2 = 9$</li></ol><div class=\"gans\"><b>Svar:</b> Modellen får 11 inputkolonner (9 med drop-first).</div>","<div class=\"gset\">A used-car price dataset has colour (5 values), fuel (petrol/diesel/electric), condition (poor/ok/good) and the numbers mileage and year.</div><ol class=\"gsteps\"><li>Colour is nominal: one-hot gives $5$ columns</li><li>Fuel is nominal: $3$ columns</li><li>Condition is ordinal ($0, 1, 2$): $1$ column; mileage and year: $1 + 1$</li><li>Total: $5 + 3 + 1 + 2 = 11$; with drop-first: $4 + 2 + 1 + 2 = 9$</li></ol><div class=\"gans\"><b>Answer:</b> The model gets 11 input columns (9 with drop-first).</div>"]},
 {id:"g-impute", n:["Gjennomsnitt og median (imputering)","Mean and median (imputation)"],
  f:["$\\bar{x} = \\frac{1}{n} \\sum_i x_i$ &nbsp; (over de $n$ kjente verdiene)<br>median = midterste verdi i sortert rekkefølge (snitt av de to midterste hvis $n$ er partall)", "$\\bar{x} = \\frac{1}{n} \\sum_i x_i$ &nbsp; (over the $n$ known values)<br>median = the middle value in sorted order (mean of the two middle ones if $n$ is even)"],
  e:["Manglende verdier kan fylles inn med snitt eller median av de <i>kjente</i> verdiene, beregnet på treningsdataene. Del på antall kjente verdier. Medianen er mer robust mot ekstreme verdier. <code>dropna()</code> fjerner i stedet hele rader.","Missing values can be filled in with the mean or median of the <i>known</i> values, computed on the training data. Divide by the number of known values. The median is more robust to extreme values. <code>dropna()</code> instead removes whole rows."],
  ex:["<div class=\"gset\">Ni Titanic-passasjerer har alder 22, 38, 26, 35, 35, ?, 54, 2, 27. Én alder mangler.</div><ol class=\"gsteps\"><li>Summen av de 8 kjente aldrene: $239$</li><li>Snitt: $\\bar{x} = \\frac{239}{8} \\approx 29{,}88$</li><li>Sortert: 2, 22, 26, 27, 35, 35, 38, 54, så median $= \\frac{27 + 35}{2} = 31$</li></ol><div class=\"gans\"><b>Svar:</b> Den manglende alderen blir 29,88 med snitt eller 31 med median; toåringen drar snittet ned, mens medianen nesten ikke påvirkes.</div>","<div class=\"gset\">Nine Titanic passengers have ages 22, 38, 26, 35, 35, ?, 54, 2, 27. One age is missing.</div><ol class=\"gsteps\"><li>Sum of the 8 known ages: $239$</li><li>Mean: $\\bar{x} = \\frac{239}{8} \\approx 29.88$</li><li>Sorted: 2, 22, 26, 27, 35, 35, 38, 54, so median $= \\frac{27 + 35}{2} = 31$</li></ol><div class=\"gans\"><b>Answer:</b> The missing age becomes 29.88 with the mean or 31 with the median; the 2-year-old pulls the mean down, the median barely moves.</div>"]},
 {id:"g-split", n:["Trenings-, validerings- og testsett","Training, validation and test sets"],
  f:["<code>train_test_split(…, test_size=t)</code>: andelen $t$ av radene som sendes inn går til den andre delen<br>$n_{\\text{test}} = t_1\\, n \\qquad n_{\\text{val}} = t_2\\, (n - n_{\\text{test}}) \\qquad n_{\\text{train}} = \\text{resten}$", "<code>train_test_split(…, test_size=t)</code>: the share $t$ of the rows passed in goes to the second part<br>$n_{\\text{test}} = t_1\\, n \\qquad n_{\\text{val}} = t_2\\, (n - n_{\\text{test}}) \\qquad n_{\\text{train}} = \\text{the rest}$"],
  e:["Trening tilpasser parametrene, validering velger hyperparametre, og test brukes bare til den endelige rapporten. Splitter du to ganger, ser det andre kallet bare restene etter det første. Ved ubalanserte klasser: <code>stratify=y</code>.","Training fits the parameters, validation picks hyperparameters, and test is only used for the final report. If you split twice, the second call only sees what is left after the first. With imbalanced classes: <code>stratify=y</code>."],
  ex:["<div class=\"gset\">Et churn-datasett har 2000 kunder. Først <code>test_size=0.2</code>, så <code>test_size=0.25</code> på resten til validering.</div><ol class=\"gsteps\"><li>$n_{\\text{test}} = 0{,}2 \\cdot 2000 = 400$</li><li>Igjen etter første splitt: $2000 - 400 = 1600$</li><li>$n_{\\text{val}} = 0{,}25 \\cdot 1600 = 400$</li><li>$n_{\\text{train}} = 1600 - 400 = 1200$</li></ol><div class=\"gans\"><b>Svar:</b> 1200 / 400 / 400 kunder, altså 60 / 20 / 20 %, ikke 60 / 25 / 15 %.</div>","<div class=\"gset\">A churn dataset has 2000 customers. First <code>test_size=0.2</code>, then <code>test_size=0.25</code> on the rest for validation.</div><ol class=\"gsteps\"><li>$n_{\\text{test}} = 0.2 \\cdot 2000 = 400$</li><li>Left after the first split: $2000 - 400 = 1600$</li><li>$n_{\\text{val}} = 0.25 \\cdot 1600 = 400$</li><li>$n_{\\text{train}} = 1600 - 400 = 1200$</li></ol><div class=\"gans\"><b>Answer:</b> 1200 / 400 / 400 customers, i.e. 60 / 20 / 20 %, not 60 / 25 / 15 %.</div>"]}
]},
// ===== 1 Logistic regression & gradient descent =====
{t:1, items:[
 {id:"g-linz", n:["Lineær kombinasjon","Linear combination"],
  f:["$z = \\sum_{i=1}^{n} w_i x_i + b = \\mathbf{w} \\cdot \\mathbf{x} + b$", "$z = \\sum_{i=1}^{n} w_i x_i + b = \\mathbf{w} \\cdot \\mathbf{x} + b$"],
  e:["Hver vekt w<sub>i</sub> sier hvor viktig feature x<sub>i</sub> er, og b er biasen (skjæringspunktet). z er et tall, ikke en vektor (prikkprodukt), og kan ha hvilken som helst verdi.","Each weight w<sub>i</sub> says how important feature x<sub>i</sub> is, and b is the bias (intercept). z is a number, not a vector (dot product), and can take any value."],
  ex:["<div class=\"gset\">En kredittmodell bruker x₁ = inntekt (i titusener) = 5 og x₂ = antall sene betalinger = 2, med w = (0,4, −1,5) og b = −0,5.</div><ol class=\"gsteps\"><li>$w_1 x_1 = 0{,}4 \\cdot 5 = 2$</li><li>$w_2 x_2 = -1{,}5 \\cdot 2 = -3$</li><li>$z = 2 - 3 - 0{,}5 = -1{,}5$</li></ol><div class=\"gans\"><b>Svar:</b> z = −1,5 er ett tall; det er negativt, så etter sigmoid heller modellen mot å avslå lånet.</div>","<div class=\"gset\">A credit-scoring model uses x₁ = income (in tens of thousands) = 5 and x₂ = late payments = 2, with w = (0.4, −1.5) and b = −0.5.</div><ol class=\"gsteps\"><li>$w_1 x_1 = 0.4 \\cdot 5 = 2$</li><li>$w_2 x_2 = -1.5 \\cdot 2 = -3$</li><li>$z = 2 - 3 - 0.5 = -1.5$</li></ol><div class=\"gans\"><b>Answer:</b> z = −1.5 is a single number; it is negative, so after the sigmoid the model leans towards rejecting the loan.</div>"]},
 {id:"g-sigmoid", n:["Sigmoid (logistisk funksjon)","Sigmoid (logistic function)"],
  f:["$\\sigma(z) = \\frac{1}{1 + e^{-z}}$<br>$y_{\\text{pred}} = \\sigma(\\mathbf{w}\\cdot\\mathbf{x} + b) \\qquad \\sigma'(z) = \\sigma(z)\\left(1 - \\sigma(z)\\right)$", "$\\sigma(z) = \\frac{1}{1 + e^{-z}}$<br>$y_{\\text{pred}} = \\sigma(\\mathbf{w}\\cdot\\mathbf{x} + b) \\qquad \\sigma'(z) = \\sigma(z)\\left(1 - \\sigma(z)\\right)$"],
  e:["Klemmer z inn i (0, 1), slik at " + y_ + " kan tolkes som p(y = 1 | x). σ(0) = 0,5, store positive z gir nær 1, store negative nær 0. Den deriverte brukes i backpropagation.","Squeezes z into (0, 1), so " + y_ + " can be read as p(y = 1 | x). σ(0) = 0.5, large positive z give close to 1, large negative close to 0. The derivative is used in backpropagation."],
  ex:["<div class=\"gset\">Et spamfilter har w = (2, −1) og b = 0,5. En e-post har x₁ = 1 «gratis»-ord og x₂ = 3 tidligere svar til avsenderen.</div><ol class=\"gsteps\"><li>$z = 2 \\cdot 1 - 1 \\cdot 3 + 0{,}5 = -0{,}5$</li><li>$e^{-z} = e^{0{,}5} \\approx 1{,}65$</li><li>$\\sigma(-0{,}5) = \\frac{1}{1 + 1{,}65} \\approx 0{,}38$</li><li>$\\sigma'(-0{,}5) = 0{,}38 \\cdot 0{,}62 \\approx 0{,}24$</li></ol><div class=\"gans\"><b>Svar:</b> p(spam) ≈ 0,38 < 0,5, så e-posten havner i innboksen.</div>","<div class=\"gset\">A spam filter has w = (2, −1) and b = 0.5. An email has x₁ = 1 \"free\"-word and x₂ = 3 earlier replies to the sender.</div><ol class=\"gsteps\"><li>$z = 2 \\cdot 1 - 1 \\cdot 3 + 0.5 = -0.5$</li><li>$e^{-z} = e^{0.5} \\approx 1.65$</li><li>$\\sigma(-0.5) = \\frac{1}{1 + 1.65} \\approx 0.38$</li><li>$\\sigma'(-0.5) = 0.38 \\cdot 0.62 \\approx 0.24$</li></ol><div class=\"gans\"><b>Answer:</b> p(spam) ≈ 0.38 < 0.5, so the email lands in the inbox.</div>"]},
 {id:"g-threshold", n:["Klassifiseringsterskel","Classification threshold"],
  f:["$\\hat{y} = 1$ hvis $y_{\\text{pred}} > \\text{terskel}$, ellers 0<br>$\\sigma(z) = p \\iff z = \\ln\\frac{p}{1 - p}$", "$\\hat{y} = 1$ if $y_{\\text{pred}} > \\text{threshold}$, otherwise 0<br>$\\sigma(z) = p \\iff z = \\ln\\frac{p}{1 - p}$"],
  e:["Standard er 0,5, som svarer til z = 0. Høyere terskel gir færre positive (recall ned, precision som regel opp). Lavere terskel gir flere positive. Terskelen endrer ikke modellen, bare hvordan prediksjonene tolkes.","The default is 0.5, which corresponds to z = 0. A higher threshold gives fewer positives (recall down, precision usually up). A lower threshold gives more positives. The threshold does not change the model, only how the predictions are read."],
  ex:["<div class=\"gset\">En screeningmodell bruker én biomarkør x med w = 2 og b = −3. Sykehuset hever terskelen fra 0,5 til 0,8.</div><ol class=\"gsteps\"><li>$z^* = \\ln\\frac{0{,}8}{0{,}2} = \\ln 4 \\approx 1{,}39$</li><li>$2x - 3 = 1{,}39 \\;\\Rightarrow\\; x = \\frac{1{,}39 + 3}{2} \\approx 2{,}19$</li><li>Terskel 0,5: $z^* = 0 \\;\\Rightarrow\\; x = 1{,}5$</li></ol><div class=\"gans\"><b>Svar:</b> Pasienter flagges nå først over x ≈ 2,19 i stedet for 1,5: færre positive, lavere recall.</div>","<div class=\"gset\">A screening model uses one biomarker x with w = 2 and b = −3. The hospital raises the threshold from 0.5 to 0.8.</div><ol class=\"gsteps\"><li>$z^* = \\ln\\frac{0.8}{0.2} = \\ln 4 \\approx 1.39$</li><li>$2x - 3 = 1.39 \\;\\Rightarrow\\; x = \\frac{1.39 + 3}{2} \\approx 2.19$</li><li>Threshold 0.5: $z^* = 0 \\;\\Rightarrow\\; x = 1.5$</li></ol><div class=\"gans\"><b>Answer:</b> Patients are now flagged only above x ≈ 2.19 instead of 1.5: fewer positives, lower recall.</div>"]},
 {id:"g-bce", n:["Binær cross-entropy (log loss)","Binary cross-entropy (log loss)"],
  f:["$L(y_{\\text{pred}}, y) = -y \\ln y_{\\text{pred}} - (1 - y)\\ln(1 - y_{\\text{pred}})$", "$L(y_{\\text{pred}}, y) = -y \\ln y_{\\text{pred}} - (1 - y)\\ln(1 - y_{\\text{pred}})$"],
  e:["Minus log-likelihood. For y = 1 teller bare −ln " + y_ + ", og for y = 0 bare −ln(1 − " + y_ + "). Tapet er 0 ved perfekt prediksjon og vokser mot ∞ når modellen er sikker og tar feil. Bruk naturlig logaritme.","Minus the log-likelihood. For y = 1 only −ln " + y_ + " counts, and for y = 0 only −ln(1 − " + y_ + "). The loss is 0 for a perfect prediction and grows towards ∞ when the model is confident and wrong. Use the natural logarithm."],
  ex:["<div class=\"gset\">Et spamfilter ser en e-post som faktisk er spam (y = 1) og predikerer $y_{\\text{pred}} = 0{,}8$.</div><ol class=\"gsteps\"><li>$y = 1$, så bare første ledd teller: $L = -\\ln y_{\\text{pred}}$</li><li>$L = -\\ln 0{,}8 \\approx 0{,}22$</li><li>Hadde den predikert $0{,}1$: $L = -\\ln 0{,}1 \\approx 2{,}30$</li></ol><div class=\"gans\"><b>Svar:</b> Tapet er 0,22; å være sikker og ta feil koster omtrent 10 ganger mer.</div>","<div class=\"gset\">A spam filter sees an email that really is spam (y = 1) and predicts $y_{\\text{pred}} = 0.8$.</div><ol class=\"gsteps\"><li>$y = 1$, so only the first term counts: $L = -\\ln y_{\\text{pred}}$</li><li>$L = -\\ln 0.8 \\approx 0.22$</li><li>Had it predicted $0.1$: $L = -\\ln 0.1 \\approx 2.30$</li></ol><div class=\"gans\"><b>Answer:</b> The loss is 0.22; being confident and wrong costs about 10 times more.</div>"]},
 {id:"g-avgloss", n:["Gjennomsnittlig tap (treningsmål)","Average loss (training objective)"],
  f:["$\\hat{\\theta} = \\arg\\min_\\theta \\frac{1}{N} \\sum_{i=1}^{N} L\\left(f(x^{(i)}; \\theta),\\, y^{(i)}\\right), \\qquad \\theta = (\\mathbf{w}, b)$", "$\\hat{\\theta} = \\arg\\min_\\theta \\frac{1}{N} \\sum_{i=1}^{N} L\\left(f(x^{(i)}; \\theta),\\, y^{(i)}\\right), \\qquad \\theta = (\\mathbf{w}, b)$"],
  e:["Trening betyr å finne parametrene som minimerer snittet av tapet over alle N treningspunkter. Husk å dele på N.","Training means finding the parameters that minimise the mean loss over all N training points. Remember to divide by N."],
  ex:["<div class=\"gset\">En churn-modell gir tre kunder: y = (1, 0, 1) og $y_{\\text{pred}} = (0{,}8, 0{,}4, 0{,}5)$.</div><ol class=\"gsteps\"><li>$L_1 = -\\ln 0{,}8 \\approx 0{,}223$</li><li>$L_2 = -\\ln(1 - 0{,}4) \\approx 0{,}511$</li><li>$L_3 = -\\ln 0{,}5 \\approx 0{,}693$</li><li>$\\frac{1}{3}(0{,}223 + 0{,}511 + 0{,}693) = \\frac{1{,}427}{3} \\approx 0{,}476$</li></ol><div class=\"gans\"><b>Svar:</b> Treningsmålet for disse parametrene er 0,476; treningen endrer w og b for å presse dette snittet ned.</div>","<div class=\"gset\">A churn model scores three customers: y = (1, 0, 1) and $y_{\\text{pred}} = (0.8, 0.4, 0.5)$.</div><ol class=\"gsteps\"><li>$L_1 = -\\ln 0.8 \\approx 0.223$</li><li>$L_2 = -\\ln(1 - 0.4) \\approx 0.511$</li><li>$L_3 = -\\ln 0.5 \\approx 0.693$</li><li>$\\frac{1}{3}(0.223 + 0.511 + 0.693) = \\frac{1.427}{3} \\approx 0.476$</li></ol><div class=\"gans\"><b>Answer:</b> The training objective for these parameters is 0.476; training changes w and b to push this mean down.</div>"]},
 {id:"g-grad-logreg", n:["Gradienten for logistisk regresjon","The gradient for logistic regression"],
  f:["$\\frac{\\partial L}{\\partial w_j} = (y_{\\text{pred}} - y)\\, x_j \\qquad \\frac{\\partial L}{\\partial b} = y_{\\text{pred}} - y$", "$\\frac{\\partial L}{\\partial w_j} = (y_{\\text{pred}} - y)\\, x_j \\qquad \\frac{\\partial L}{\\partial b} = y_{\\text{pred}} - y$"],
  e:["Med cross-entropy og sigmoid blir gradienten bare feilen ganger inputen. Negativ gradient betyr at tapet minker når parameteren øker.","With cross-entropy and sigmoid, the gradient is just the error times the input. A negative gradient means the loss decreases when the parameter increases."],
  ex:["<div class=\"gset\">En kunde som faktisk sluttet (y = 1) har x = (2 klager, 1 prisøkning), og modellen predikerer $y_{\\text{pred}} = 0{,}5$.</div><ol class=\"gsteps\"><li>Feil: $y_{\\text{pred}} - y = 0{,}5 - 1 = -0{,}5$</li><li>$\\frac{\\partial L}{\\partial w_1} = -0{,}5 \\cdot 2 = -1$</li><li>$\\frac{\\partial L}{\\partial w_2} = -0{,}5 \\cdot 1 = -0{,}5, \\quad \\frac{\\partial L}{\\partial b} = -0{,}5$</li></ol><div class=\"gans\"><b>Svar:</b> Alle gradientene er negative, så å øke vektene og b senker tapet og dytter prediksjonen mot 1.</div>","<div class=\"gset\">A customer who did churn (y = 1) has x = (2 complaints, 1 price rise), and the model predicts $y_{\\text{pred}} = 0.5$.</div><ol class=\"gsteps\"><li>Error: $y_{\\text{pred}} - y = 0.5 - 1 = -0.5$</li><li>$\\frac{\\partial L}{\\partial w_1} = -0.5 \\cdot 2 = -1$</li><li>$\\frac{\\partial L}{\\partial w_2} = -0.5 \\cdot 1 = -0.5, \\quad \\frac{\\partial L}{\\partial b} = -0.5$</li></ol><div class=\"gans\"><b>Answer:</b> All gradients are negative, so increasing the weights and b lowers the loss and pushes the prediction towards 1.</div>"]},
 {id:"g-gd", n:["Gradient descent","Gradient descent"],
  f:["$\\theta_{t+1} = \\theta_t - \\eta\\, \\frac{\\partial L}{\\partial \\theta}$", "$\\theta_{t+1} = \\theta_t - \\eta\\, \\frac{\\partial L}{\\partial \\theta}$"],
  e:["Gradienten peker mot økende tap, så vi går motsatt vei (minustegnet). η er læringsraten, en hyperparameter. For stor η gir oscillasjon eller divergens. For liten η gir svært langsom læring. Oppdater alle parametre, også b.","The gradient points towards increasing loss, so we move the opposite way (the minus sign). η is the learning rate, a hyperparameter. Too large an η gives oscillation or divergence. Too small an η gives very slow learning. Update every parameter, b too."],
  ex:["<div class=\"gset\">En boligprismodell har vekt w = 3 for boareal. Gradienten er ∂L/∂w = 4 og η = 0,25.</div><ol class=\"gsteps\"><li>Steg: $\\eta \\cdot \\frac{\\partial L}{\\partial w} = 0{,}25 \\cdot 4 = 1$</li><li>$w = 3 - 1 = 2$</li><li>Med $\\eta = 1$: $w = 3 - 4 = -1$ (trolig for langt)</li></ol><div class=\"gans\"><b>Svar:</b> Den nye vekten er 2; positiv gradient betyr at tapet øker med w, så w går ned.</div>","<div class=\"gset\">A house-price model has weight w = 3 for floor area. The gradient is ∂L/∂w = 4 and η = 0.25.</div><ol class=\"gsteps\"><li>Step: $\\eta \\cdot \\frac{\\partial L}{\\partial w} = 0.25 \\cdot 4 = 1$</li><li>$w = 3 - 1 = 2$</li><li>With $\\eta = 1$: $w = 3 - 4 = -1$ (likely overshoot)</li></ol><div class=\"gans\"><b>Answer:</b> The new weight is 2; the positive gradient means the loss rises with w, so w goes down.</div>"]}
]},
// ===== 2 Classification metrics =====
{t:2, items:[
 {id:"g-cm", n:["Confusion matrix","Confusion matrix"],
  f:["$TP$ = sann positiv · $FN$ = sann positiv, predikert negativ · $FP$ = sann negativ, predikert positiv · $TN$ = sann negativ<br>$P = TP + FN$ (alle positive) · $N = TN + FP$ (alle negative)", "$TP$ = true positive · $FN$ = actually positive, predicted negative · $FP$ = actually negative, predicted positive · $TN$ = true negative<br>$P = TP + FN$ (all positives) · $N = TN + FP$ (all negatives)"],
  e:["Riktige prediksjoner ligger på diagonalen, feil utenfor. Sjekk alltid om radene er sann eller predikert klasse, og hvilken klasse som er positiv.","Correct predictions lie on the diagonal, errors off it. Always check whether the rows are the true or the predicted class, and which class is positive."],
  ex:["<div class=\"gset\">Et spamfilter testes på 100 e-poster: 30 er spam, og 24 av dem flagges; 7 av de 70 vanlige e-postene flagges også.</div><ol class=\"gsteps\"><li>$TP = 24, \\quad FN = 30 - 24 = 6$</li><li>$FP = 7, \\quad TN = 70 - 7 = 63$</li><li>$P = 24 + 6 = 30, \\quad N = 63 + 7 = 70$</li><li>Diagonalen: $24 + 63 = 87$ riktige, $6 + 7 = 13$ feil</li></ol><div class=\"gans\"><b>Svar:</b> Matrisen er [[TP 24, FN 6], [FP 7, TN 63]] med spam som positiv klasse.</div>","<div class=\"gset\">A spam filter is tested on 100 emails: 30 are spam and 24 of these are flagged; 7 of the 70 normal emails are also flagged.</div><ol class=\"gsteps\"><li>$TP = 24, \\quad FN = 30 - 24 = 6$</li><li>$FP = 7, \\quad TN = 70 - 7 = 63$</li><li>$P = 24 + 6 = 30, \\quad N = 63 + 7 = 70$</li><li>Diagonal: $24 + 63 = 87$ correct, $6 + 7 = 13$ errors</li></ol><div class=\"gans\"><b>Answer:</b> The matrix is [[TP 24, FN 6], [FP 7, TN 63]] with spam as the positive class.</div>"]},
 {id:"g-recall", n:["Recall / sensitivitet / TPR","Recall / sensitivity / TPR"],
  f:["$\\text{TPR} = \\text{Recall} = \\frac{TP}{P} = \\frac{TP}{TP + FN}$", "$\\text{TPR} = \\text{Recall} = \\frac{TP}{P} = \\frac{TP}{TP + FN}$"],
  e:["Andelen av de faktisk positive som blir funnet. Viktig når falske negative er dyre (alvorlig sykdom, screening). Deler på <i>sanne</i> positive.","The share of the actual positives that are found. Important when false negatives are costly (serious disease, screening). Divides by the <i>actual</i> positives."],
  ex:["<div class=\"gset\">Et sykehus screener 1000 personer; 50 av dem har sykdommen, og testen flagger 45 av de 50.</div><ol class=\"gsteps\"><li>$TP = 45, \\quad FN = 50 - 45 = 5$</li><li>$P = TP + FN = 50$</li><li>$\\text{Recall} = \\frac{45}{50} = 0{,}9$</li></ol><div class=\"gans\"><b>Svar:</b> Testen finner 90 % av de syke, men 5 syke pasienter sendes hjem.</div>","<div class=\"gset\">A hospital screens 1000 people; 50 of them have the disease and the test flags 45 of those 50.</div><ol class=\"gsteps\"><li>$TP = 45, \\quad FN = 50 - 45 = 5$</li><li>$P = TP + FN = 50$</li><li>$\\text{Recall} = \\frac{45}{50} = 0.9$</li></ol><div class=\"gans\"><b>Answer:</b> The test finds 90 % of the sick, but 5 sick patients are sent home.</div>"]},
 {id:"g-spec", n:["Spesifisitet / TNR","Specificity / TNR"],
  f:["$\\text{TNR} = \\frac{TN}{N} = \\frac{TN}{TN + FP}$", "$\\text{TNR} = \\frac{TN}{N} = \\frac{TN}{TN + FP}$"],
  e:["Andelen av de faktisk negative som blir korrekt klassifisert som negative.","The share of the actual negatives that are correctly classified as negative."],
  ex:["<div class=\"gset\">I den samme screeningen er 950 friske; 893 av dem tester negativt, og 57 får falsk alarm.</div><ol class=\"gsteps\"><li>$TN = 893, \\quad FP = 57$</li><li>$N = TN + FP = 893 + 57 = 950$</li><li>$\\text{TNR} = \\frac{893}{950} = 0{,}94$</li></ol><div class=\"gans\"><b>Svar:</b> 94 % av de friske blir korrekt friskmeldt.</div>","<div class=\"gset\">In the same screening, 950 people are healthy; 893 of them test negative and 57 get a false alarm.</div><ol class=\"gsteps\"><li>$TN = 893, \\quad FP = 57$</li><li>$N = TN + FP = 893 + 57 = 950$</li><li>$\\text{TNR} = \\frac{893}{950} = 0.94$</li></ol><div class=\"gans\"><b>Answer:</b> 94 % of the healthy are correctly cleared.</div>"]},
 {id:"g-fpr", n:["False positive rate","False positive rate"],
  f:["$\\text{FPR} = \\frac{FP}{N} = \\frac{FP}{FP + TN} = 1 - \\text{TNR}$", "$\\text{FPR} = \\frac{FP}{N} = \\frac{FP}{FP + TN} = 1 - \\text{TNR}$"],
  e:["Sannsynligheten for falsk alarm. Dette er x-aksen i ROC-kurven. Deler på alle negative, ikke på de predikert positive (det ville vært 1 − precision).","The probability of a false alarm. This is the x-axis of the ROC curve. Divides by all negatives, not by the predicted positives (that would be 1 − precision)."],
  ex:["<div class=\"gset\">En banks svindeldetektor sjekker 2000 legitime transaksjoner og blokkerer 40 av dem feilaktig.</div><ol class=\"gsteps\"><li>$FP = 40, \\quad TN = 2000 - 40 = 1960$</li><li>$\\text{FPR} = \\frac{40}{2000} = 0{,}02$</li><li>Sjekk: $\\text{TNR} = \\frac{1960}{2000} = 0{,}98$, så $1 - 0{,}98 = 0{,}02$</li></ol><div class=\"gans\"><b>Svar:</b> 2 % av ærlige kunder får kortet sperret; dette er x-koordinaten til detektorens punkt på ROC-kurven.</div>","<div class=\"gset\">A bank's fraud detector checks 2000 legitimate transactions and wrongly blocks 40 of them.</div><ol class=\"gsteps\"><li>$FP = 40, \\quad TN = 2000 - 40 = 1960$</li><li>$\\text{FPR} = \\frac{40}{2000} = 0.02$</li><li>Check: $\\text{TNR} = \\frac{1960}{2000} = 0.98$, so $1 - 0.98 = 0.02$</li></ol><div class=\"gans\"><b>Answer:</b> 2 % of honest customers get their card blocked; this is the x-coordinate of the detector's point on the ROC curve.</div>"]},
 {id:"g-precision", n:["Precision / PPV","Precision / PPV"],
  f:["$\\text{Precision} = \\frac{TP}{TP + FP}$", "$\\text{Precision} = \\frac{TP}{TP + FP}$"],
  e:["Andelen av de predikert positive som faktisk er positive. Viktig når falske alarmer er dyre. Avhenger av klassefordelingen: med få positive kan precision bli lav selv med lav FPR.","The share of the predicted positives that are actually positive. Important when false alarms are costly. Depends on the class distribution: with few positives, precision can be low even with a low FPR."],
  ex:["<div class=\"gset\">Screeningtesten fra recall-eksemplet gir TP = 45 syke og FP = 57 friske blant de flaggede.</div><ol class=\"gsteps\"><li>Predikert positive: $45 + 57 = 102$</li><li>$\\text{Precision} = \\frac{45}{102} \\approx 0{,}44$</li><li>Til sammenligning: $\\text{FPR} = \\frac{57}{950} = 0{,}06$</li></ol><div class=\"gans\"><b>Svar:</b> Bare 44 % av dem som kalles inn er faktisk syke, selv om FPR bare er 6 %, fordi sykdommen er sjelden.</div>","<div class=\"gset\">The screening test from the recall example gives TP = 45 sick and FP = 57 healthy among those flagged.</div><ol class=\"gsteps\"><li>Predicted positive: $45 + 57 = 102$</li><li>$\\text{Precision} = \\frac{45}{102} \\approx 0.44$</li><li>For comparison: $\\text{FPR} = \\frac{57}{950} = 0.06$</li></ol><div class=\"gans\"><b>Answer:</b> Only 44 % of those called back are actually sick, even though the FPR is only 6 %, because the disease is rare.</div>"]},
 {id:"g-accuracy", n:["Accuracy (treffsikkerhet)","Accuracy"],
  f:["$\\text{Accuracy} = \\frac{TP + TN}{TP + TN + FP + FN}$", "$\\text{Accuracy} = \\frac{TP + TN}{TP + TN + FP + FN}$"],
  e:["Andelen riktige prediksjoner. Misvisende ved ubalanserte klasser: en modell som alltid sier «negativ» får 95 % med 5 % positive, men recall 0.","The share of correct predictions. Misleading with imbalanced classes: a model that always says “negative” gets 95 % with 5 % positives, but recall 0."],
  ex:["<div class=\"gset\">Av 1000 korttransaksjoner er 10 svindel. Modell A sier alltid «legitim». Modell B får TP = 8, FN = 2, FP = 30, TN = 960.</div><ol class=\"gsteps\"><li>A: $\\frac{0 + 990}{1000} = 0{,}99$</li><li>A: recall $= \\frac{0}{10} = 0$</li><li>B: $\\frac{8 + 960}{1000} = 0{,}968$</li></ol><div class=\"gans\"><b>Svar:</b> A har høyest accuracy, men fanger ingen svindel; B er den nyttige modellen til tross for 96,8 %.</div>","<div class=\"gset\">Of 1000 card transactions, 10 are fraud. Model A always says \"legit\". Model B gets TP = 8, FN = 2, FP = 30, TN = 960.</div><ol class=\"gsteps\"><li>A: $\\frac{0 + 990}{1000} = 0.99$</li><li>A: recall $= \\frac{0}{10} = 0$</li><li>B: $\\frac{8 + 960}{1000} = 0.968$</li></ol><div class=\"gans\"><b>Answer:</b> A has the higher accuracy but catches no fraud; B is the useful model despite 96.8 %.</div>"]},
 {id:"g-f1", n:["F1-score","F1 score"],
  f:["$F_1 = \\frac{2 \\cdot \\text{Precision} \\cdot \\text{Recall}}{\\text{Precision} + \\text{Recall}}$", "$F_1 = \\frac{2 \\cdot \\text{Precision} \\cdot \\text{Recall}}{\\text{Precision} + \\text{Recall}}$"],
  e:["Harmonisk snitt av precision og recall. Den blir lav hvis én av dem er lav. Precision = recall nøyaktig når FP = FN.","The harmonic mean of precision and recall. It is low if either of them is low. Precision = recall exactly when FP = FN."],
  ex:["<div class=\"gset\">En bildeklassifiserer for «katt» finner TP = 40 katter, bommer på FN = 20 og gir FP = 10 falske katter.</div><ol class=\"gsteps\"><li>$\\text{Precision} = \\frac{40}{40 + 10} = 0{,}8$</li><li>$\\text{Recall} = \\frac{40}{40 + 20} \\approx 0{,}667$</li><li>$F_1 = \\frac{2 \\cdot 0{,}8 \\cdot 0{,}667}{0{,}8 + 0{,}667} = \\frac{1{,}067}{1{,}467} \\approx 0{,}73$</li></ol><div class=\"gans\"><b>Svar:</b> F1 ≈ 0,73 ligger nærmere den svakeste, recall, enn et vanlig snitt skulle tilsi.</div>","<div class=\"gset\">An image classifier for \"cat\" finds TP = 40 cats, misses FN = 20 and gives FP = 10 false cats.</div><ol class=\"gsteps\"><li>$\\text{Precision} = \\frac{40}{40 + 10} = 0.8$</li><li>$\\text{Recall} = \\frac{40}{40 + 20} \\approx 0.667$</li><li>$F_1 = \\frac{2 \\cdot 0.8 \\cdot 0.667}{0.8 + 0.667} = \\frac{1.067}{1.467} \\approx 0.73$</li></ol><div class=\"gans\"><b>Answer:</b> F1 ≈ 0.73 lies closer to the weaker recall than the simple mean would suggest.</div>"]},
 {id:"g-auc", n:["ROC-kurve og AUC","ROC curve and AUC"],
  f:["ROC: $(\\text{FPR}, \\text{TPR})$ for alle terskler fra 1 til 0, fra $(0, 0)$ til $(1, 1)$<br>$\\text{AUC} = P\\left(s(x^+) > s(x^-)\\right) = \\frac{\\text{antall par der positiv har høyest skår}}{n^+ \\cdot n^-}$", "ROC: $(\\text{FPR}, \\text{TPR})$ for every threshold from 1 to 0, from $(0, 0)$ to $(1, 1)$<br>$\\text{AUC} = P\\left(s(x^+) > s(x^-)\\right) = \\frac{\\text{number of pairs where the positive scores higher}}{n^+ \\cdot n^-}$"],
  e:["Diagonalen er tilfeldig gjetning (AUC = 0,5), og maks er 1. AUC < 0,5 betyr systematisk feil rangering; snur du prediksjonene får du 1 − AUC. Ved sterk ubalanse er en precision–recall-kurve ofte mer informativ.","The diagonal is random guessing (AUC = 0.5), and the maximum is 1. AUC < 0.5 means systematically wrong ranking; flipping the predictions gives 1 − AUC. Under strong imbalance a precision–recall curve is often more informative."],
  ex:["<div class=\"gset\">En churn-modell gir skår til tre kunder som sluttet (0,9, 0,8, 0,4) og tre som ble (0,7, 0,3, 0,2).</div><ol class=\"gsteps\"><li>Par: $n^+ \\cdot n^- = 3 \\cdot 3 = 9$</li><li>0,9 og 0,8 slår alle tre som ble: $3 + 3 = 6$</li><li>0,4 slår 0,3 og 0,2, men ikke 0,7: $2$</li><li>$\\text{AUC} = \\frac{6 + 2}{9} \\approx 0{,}89$</li></ol><div class=\"gans\"><b>Svar:</b> I 89 % av parene (sluttet, ble) får kunden som sluttet høyest skår.</div>","<div class=\"gset\">A churn model scores three customers who left (0.9, 0.8, 0.4) and three who stayed (0.7, 0.3, 0.2).</div><ol class=\"gsteps\"><li>Pairs: $n^+ \\cdot n^- = 3 \\cdot 3 = 9$</li><li>0.9 and 0.8 beat all three stayers: $3 + 3 = 6$</li><li>0.4 beats 0.3 and 0.2, but not 0.7: $2$</li><li>$\\text{AUC} = \\frac{6 + 2}{9} \\approx 0.89$</li></ol><div class=\"gans\"><b>Answer:</b> In 89 % of churner–stayer pairs the churner gets the higher score.</div>"]}
]},
// ===== 3 Bayes & imbalanced data =====
{t:3, items:[
 {id:"g-bayes", n:["Bayes' teorem","Bayes' theorem"],
  f:["$p(C_k \\mid x) = \\frac{p(x \\mid C_k)\\, p(C_k)}{p(x)}$", "$p(C_k \\mid x) = \\frac{p(x \\mid C_k)\\, p(C_k)}{p(x)}$"],
  e:["p(C<sub>k</sub>) er prior (klassefordelingen), p(x|C<sub>k</sub>) er likelihood, p(x) er evidens og p(C<sub>k</sub>|x) er posterior. p(x) er lik for alle klasser og sikrer at posteriorene summerer til 1.","p(C<sub>k</sub>) is the prior (the class distribution), p(x|C<sub>k</sub>) is the likelihood, p(x) is the evidence and p(C<sub>k</sub>|x) is the posterior. p(x) is the same for all classes and makes the posteriors sum to 1."],
  ex:["<div class=\"gset\">30 % av all e-post er spam. Ordet «vinner» står i 40 % av spam og 5 % av vanlig e-post. En e-post inneholder «vinner».</div><ol class=\"gsteps\"><li>Likelihood · prior: $0{,}4 \\cdot 0{,}3 = 0{,}12$</li><li>Evidens: $p(x) = 0{,}12 + 0{,}05 \\cdot 0{,}7 = 0{,}155$</li><li>$p(\\text{spam} \\mid x) = \\frac{0{,}12}{0{,}155} \\approx 0{,}77$</li></ol><div class=\"gans\"><b>Svar:</b> Ordet løfter spamsannsynligheten fra prior 30 % til posterior 77 %.</div>","<div class=\"gset\">30 % of all email is spam. The word \"winner\" appears in 40 % of spam and 5 % of normal email. An email contains \"winner\".</div><ol class=\"gsteps\"><li>Likelihood · prior: $0.4 \\cdot 0.3 = 0.12$</li><li>Evidence: $p(x) = 0.12 + 0.05 \\cdot 0.7 = 0.155$</li><li>$p(\\text{spam} \\mid x) = \\frac{0.12}{0.155} \\approx 0.77$</li></ol><div class=\"gans\"><b>Answer:</b> The word raises the spam probability from the prior 30 % to the posterior 77 %.</div>"]},
 {id:"g-totalprob", n:["Total sannsynlighet (evidensen)","Total probability (the evidence)"],
  f:["$p(x) = \\sum_k p(x \\mid C_k)\\, p(C_k)$<br>To klasser: $p(x) = p(x \\mid C)\\, p(C) + p(x \\mid \\neg C)\\, p(\\neg C)$", "$p(x) = \\sum_k p(x \\mid C_k)\\, p(C_k)$<br>Two classes: $p(x) = p(x \\mid C)\\, p(C) + p(x \\mid \\neg C)\\, p(\\neg C)$"],
  e:["Typisk i testoppgaver: p(+) = sensitivitet · prevalens + falsk-positiv-rate · (1 − prevalens). Med lav prevalens kan p(syk | +) bli overraskende lav.","Typical in test questions: p(+) = sensitivity · prevalence + false-positive rate · (1 − prevalence). With low prevalence p(sick | +) can be surprisingly low."],
  ex:["<div class=\"gset\">En sykdom har prevalens 1 %. Screeningtesten har sensitivitet 90 % og falsk-positiv-rate 5 %. En pasient tester positivt.</div><ol class=\"gsteps\"><li>Syk og positiv: $0{,}9 \\cdot 0{,}01 = 0{,}009$</li><li>Frisk og positiv: $0{,}05 \\cdot 0{,}99 = 0{,}0495$</li><li>$p(+) = 0{,}009 + 0{,}0495 = 0{,}0585$</li><li>$p(\\text{syk} \\mid +) = \\frac{0{,}009}{0{,}0585} \\approx 0{,}154$</li></ol><div class=\"gans\"><b>Svar:</b> Bare omtrent 15,4 % av de positive er faktisk syke, fordi det er så mange flere friske enn syke.</div>","<div class=\"gset\">A disease has prevalence 1 %. The screening test has sensitivity 90 % and false-positive rate 5 %. A patient tests positive.</div><ol class=\"gsteps\"><li>Sick and positive: $0.9 \\cdot 0.01 = 0.009$</li><li>Healthy and positive: $0.05 \\cdot 0.99 = 0.0495$</li><li>$p(+) = 0.009 + 0.0495 = 0.0585$</li><li>$p(\\text{sick} \\mid +) = \\frac{0.009}{0.0585} \\approx 0.154$</li></ol><div class=\"gans\"><b>Answer:</b> Only about 15.4 % of positive patients are actually sick, because healthy people vastly outnumber the sick.</div>"]},
 {id:"g-naivebayes", n:["Naiv Bayes","Naive Bayes"],
  f:["$p(C_k \\mid x) \\propto p(C_k) \\prod_{i=1}^{n} p(x_i \\mid C_k)$<br>$\\hat{y} = \\arg\\max_k\\, p(C_k) \\prod_i p(x_i \\mid C_k)$", "$p(C_k \\mid x) \\propto p(C_k) \\prod_{i=1}^{n} p(x_i \\mid C_k)$<br>$\\hat{y} = \\arg\\max_k\\, p(C_k) \\prod_i p(x_i \\mid C_k)$"],
  e:["Antar at featurene er uavhengige gitt klassen, slik at simultanfordelingen blir et produkt. Skårene er ikke kalibrerte sannsynligheter, men rekkefølgen er nok for argmax. Ikke glem prior.","Assumes the features are independent given the class, so the joint distribution becomes a product. The scores are not calibrated probabilities, but their order is enough for the argmax. Do not forget the prior."],
  ex:["<div class=\"gset\">Et spamfilter ser ordene «vinn» og «møte». p(spam) = 0,4, p(vinn | spam) = 0,3, p(møte | spam) = 0,1; p(ham) = 0,6, p(vinn | ham) = 0,05, p(møte | ham) = 0,2.</div><ol class=\"gsteps\"><li>$s_{\\text{spam}} = 0{,}4 \\cdot 0{,}3 \\cdot 0{,}1 = 0{,}012$</li><li>$s_{\\text{ham}} = 0{,}6 \\cdot 0{,}05 \\cdot 0{,}2 = 0{,}006$</li><li>$\\arg\\max = \\text{spam}$ $(0{,}012 > 0{,}006)$</li></ol><div class=\"gans\"><b>Svar:</b> E-posten klassifiseres som spam; skårene er ikke sannsynligheter, men rekkefølgen avgjør.</div>","<div class=\"gset\">A spam filter sees the words \"win\" and \"meeting\". p(spam) = 0.4, p(win | spam) = 0.3, p(meeting | spam) = 0.1; p(ham) = 0.6, p(win | ham) = 0.05, p(meeting | ham) = 0.2.</div><ol class=\"gsteps\"><li>$s_{\\text{spam}} = 0.4 \\cdot 0.3 \\cdot 0.1 = 0.012$</li><li>$s_{\\text{ham}} = 0.6 \\cdot 0.05 \\cdot 0.2 = 0.006$</li><li>$\\arg\\max = \\text{spam}$ $(0.012 > 0.006)$</li></ol><div class=\"gans\"><b>Answer:</b> The email is classified as spam; the scores are not probabilities, but their order decides.</div>"]},
 {id:"g-normalise", n:["Normalisering av posterior","Normalising the posterior"],
  f:["$p(C_k \\mid x) = \\frac{s_k}{\\sum_j s_j}, \\qquad s_k = p(C_k) \\prod_i p(x_i \\mid C_k)$", "$p(C_k \\mid x) = \\frac{s_k}{\\sum_j s_j}, \\qquad s_k = p(C_k) \\prod_i p(x_i \\mid C_k)$"],
  e:["Del hver skår på summen av skårene for å få sannsynligheter som summerer til 1. Den rå skåren s<sub>k</sub> er ikke en sannsynlighet.","Divide each score by the sum of the scores to get probabilities that sum to 1. The raw score s<sub>k</sub> is not a probability."],
  ex:["<div class=\"gset\">En nyhetsklassifiserer får en artikkel med to ord. Prior sport/politikk/kultur = 0,5/0,3/0,2; likelihoods (0,4, 0,6), (0,5, 0,4), (0,5, 0,2).</div><ol class=\"gsteps\"><li>$s_1 = 0{,}5 \\cdot 0{,}4 \\cdot 0{,}6 = 0{,}12$</li><li>$s_2 = 0{,}3 \\cdot 0{,}5 \\cdot 0{,}4 = 0{,}06, \\quad s_3 = 0{,}2 \\cdot 0{,}5 \\cdot 0{,}2 = 0{,}02$</li><li>Sum: $0{,}12 + 0{,}06 + 0{,}02 = 0{,}2$</li><li>$p = \\left(\\frac{0{,}12}{0{,}2}, \\frac{0{,}06}{0{,}2}, \\frac{0{,}02}{0{,}2}\\right) = (0{,}6, 0{,}3, 0{,}1)$</li></ol><div class=\"gans\"><b>Svar:</b> Artikkelen er sport med sannsynlighet 0,6; de normaliserte verdiene summerer til 1.</div>","<div class=\"gset\">A news classifier scores an article with two words. Priors sport/politics/culture = 0.5/0.3/0.2; word likelihoods (0.4, 0.6), (0.5, 0.4), (0.5, 0.2).</div><ol class=\"gsteps\"><li>$s_1 = 0.5 \\cdot 0.4 \\cdot 0.6 = 0.12$</li><li>$s_2 = 0.3 \\cdot 0.5 \\cdot 0.4 = 0.06, \\quad s_3 = 0.2 \\cdot 0.5 \\cdot 0.2 = 0.02$</li><li>Sum: $0.12 + 0.06 + 0.02 = 0.2$</li><li>$p = \\left(\\frac{0.12}{0.2}, \\frac{0.06}{0.2}, \\frac{0.02}{0.2}\\right) = (0.6, 0.3, 0.1)$</li></ol><div class=\"gans\"><b>Answer:</b> The article is sport with probability 0.6; the normalised values sum to 1.</div>"]},
 {id:"g-prior-shift", n:["Bayes-grense og prior shift","Bayes boundary and prior shift"],
  f:["Velg $C = 1$ når $p(x \\mid C{=}1)\\, p(C{=}1) > p(x \\mid C{=}0)\\, p(C{=}0)$<br>To Gauss med $\\mu = \\mp 1$, $\\sigma = 1$: $x^* = -\\frac{1}{2} \\ln\\frac{p(C=1)}{p(C=0)}$", "Choose $C = 1$ when $p(x \\mid C{=}1)\\, p(C{=}1) > p(x \\mid C{=}0)\\, p(C{=}0)$<br>Two Gaussians with $\\mu = \\mp 1$, $\\sigma = 1$: $x^* = -\\frac{1}{2} \\ln\\frac{p(C=1)}{p(C=0)}$"],
  e:["Grensen ligger der de vektede tetthetene er like. Endres prior, flyttes grensen bort fra den hyppige klassen, så den «vinner» et større område. Ved skjeve klasser dominerer p(C<sub>k</sub>) prediksjonene (prior probability shift).","The boundary is where the weighted densities are equal. If the prior changes, the boundary moves away from the frequent class, so it “wins” a larger region. With imbalanced classes p(C<sub>k</sub>) dominates the predictions (prior probability shift)."],
  ex:["<div class=\"gset\">En svindelmodell bruker én standardisert feature: legitim (C = 0) ~ N(−1, 1), svindel (C = 1) ~ N(1, 1). Bare 20 % av sakene er svindel.</div><ol class=\"gsteps\"><li>Like prior: $x^* = -\\frac{1}{2} \\ln 1 = 0$</li><li>$\\frac{p(C=1)}{p(C=0)} = \\frac{0{,}2}{0{,}8} = 0{,}25, \\quad \\ln 0{,}25 \\approx -1{,}39$</li><li>$x^* = -\\frac{1}{2} \\cdot (-1{,}39) \\approx 0{,}69$</li></ol><div class=\"gans\"><b>Svar:</b> Grensen flyttes fra 0 til 0,69, bort fra den hyppige legitime klassen, så en sak må se mer mistenkelig ut før den flagges.</div>","<div class=\"gset\">A fraud model uses one standardised feature: legit (C = 0) ~ N(−1, 1), fraud (C = 1) ~ N(1, 1). Only 20 % of cases are fraud.</div><ol class=\"gsteps\"><li>Equal priors: $x^* = -\\frac{1}{2} \\ln 1 = 0$</li><li>$\\frac{p(C=1)}{p(C=0)} = \\frac{0.2}{0.8} = 0.25, \\quad \\ln 0.25 \\approx -1.39$</li><li>$x^* = -\\frac{1}{2} \\cdot (-1.39) \\approx 0.69$</li></ol><div class=\"gans\"><b>Answer:</b> The boundary moves from 0 to 0.69, away from the frequent legit class, so a case must look more fraudulent before it is flagged.</div>"]},
 {id:"g-resample", n:["Under- og oversampling","Under- and oversampling"],
  f:["Undersampling: $n_{\\text{maj}} \\to n_{\\min}$, totalt $2\\, n_{\\min}$<br>Oversampling: $n_{\\min} \\to n_{\\text{maj}}$, totalt $2\\, n_{\\text{maj}}$, duplikater $= n_{\\text{maj}} - n_{\\min}$", "Undersampling: $n_{\\text{maj}} \\to n_{\\min}$, total $2\\, n_{\\min}$<br>Oversampling: $n_{\\min} \\to n_{\\text{maj}}$, total $2\\, n_{\\text{maj}}$, duplicates $= n_{\\text{maj}} - n_{\\min}$"],
  e:["Undersampling kaster data og kan gi undertilpasning. Oversampling kopierer minoritetsklassen og kan gi overtilpasning. Teknikkene kan kombineres. Resample bare treningsdataene.","Undersampling throws data away and can cause underfitting. Oversampling copies the minority class and can cause overfitting. The techniques can be combined. Resample only the training data."],
  ex:["<div class=\"gset\">Et treningssett med kortsvindel har 100 svindelsaker og 1000 legitime.</div><ol class=\"gsteps\"><li>Undersampling: behold $100$ legitime, totalt $2 \\cdot 100 = 200$</li><li>Oversampling: kopier svindel opp til $1000$, totalt $2 \\cdot 1000 = 2000$</li><li>Duplikater: $1000 - 100 = 900$</li></ol><div class=\"gans\"><b>Svar:</b> Undersampling kaster 900 legitime rader; oversampling legger til 900 kopier av svindelsaker. Bare treningssettet resamples.</div>","<div class=\"gset\">A credit-card training set has 100 fraud cases and 1000 legitimate ones.</div><ol class=\"gsteps\"><li>Undersampling: keep $100$ of the legit, total $2 \\cdot 100 = 200$</li><li>Oversampling: copy fraud up to $1000$, total $2 \\cdot 1000 = 2000$</li><li>Duplicates: $1000 - 100 = 900$</li></ol><div class=\"gans\"><b>Answer:</b> Undersampling throws away 900 legit rows; oversampling adds 900 copies of fraud cases. Only the training set is resampled.</div>"]},
 {id:"g-classweights", n:["Klassevekter","Class weights"],
  f:["$w_c = \\frac{n}{K \\cdot n_c}$", "$w_c = \\frac{n}{K \\cdot n_c}$"],
  e:["n er antall eksempler, K antall klasser og n<sub>c</sub> antall i klasse c. Vektene er omvendt proporsjonale med klassestørrelsen, så sjeldne klasser får størst vekt (<code>class_weight=\"balanced\"</code>).","n is the number of examples, K the number of classes and n<sub>c</sub> the count in class c. The weights are inversely proportional to the class size, so rare classes get the largest weight (<code>class_weight=\"balanced\"</code>)."],
  ex:["<div class=\"gset\">Et teleselskap har 9000 kunder som ble og 1000 som sluttet (n = 10 000, K = 2).</div><ol class=\"gsteps\"><li>$w_{\\text{churn}} = \\frac{10\\,000}{2 \\cdot 1000} = 5$</li><li>$w_{\\text{stay}} = \\frac{10\\,000}{2 \\cdot 9000} \\approx 0{,}56$</li><li>Sjekk: $5 \\cdot 1000 = 5000 \\approx 0{,}556 \\cdot 9000$</li></ol><div class=\"gans\"><b>Svar:</b> Hver kunde som sluttet teller 5 ganger i tapet, så begge klassene bidrar like mye totalt.</div>","<div class=\"gset\">A telecom has 9000 customers who stayed and 1000 who churned (n = 10,000, K = 2).</div><ol class=\"gsteps\"><li>$w_{\\text{churn}} = \\frac{10\\,000}{2 \\cdot 1000} = 5$</li><li>$w_{\\text{stay}} = \\frac{10\\,000}{2 \\cdot 9000} \\approx 0.56$</li><li>Check: $5 \\cdot 1000 = 5000 \\approx 0.556 \\cdot 9000$</li></ol><div class=\"gans\"><b>Answer:</b> Each churner counts 5 times in the loss, so both classes contribute equally in total.</div>"]},
 {id:"g-weightedbce", n:["Vektet cross-entropy","Weighted cross-entropy"],
  f:["$L(y_{\\text{pred}}, y) = -w_1\\, y \\ln y_{\\text{pred}} - w_0\\, (1 - y) \\ln(1 - y_{\\text{pred}})$", "$L(y_{\\text{pred}}, y) = -w_1\\, y \\ln y_{\\text{pred}} - w_0\\, (1 - y) \\ln(1 - y_{\\text{pred}})$"],
  e:["w<sub>1</sub> vekter leddet for klasse y = 1 og w<sub>0</sub> leddet for y = 0. Større vekt på en klasse gjør feil på den dyrere, så modellen prioriterer den.","w<sub>1</sub> weights the term for class y = 1 and w<sub>0</sub> the term for y = 0. A larger weight on a class makes errors on it more costly, so the model prioritises it."],
  ex:["<div class=\"gset\">En sykdomsmodell bruker w₁ = 9 for syke og w₀ = 1 for friske. En syk pasient (y = 1) får $y_{\\text{pred}} = 0{,}25$.</div><ol class=\"gsteps\"><li>Uvektet: $-\\ln 0{,}25 \\approx 1{,}386$</li><li>Vektet: $L = 9 \\cdot 1{,}386 \\approx 12{,}48$</li><li>Frisk pasient med $y_{\\text{pred}} = 0{,}25$: $L = -1 \\cdot \\ln 0{,}75 \\approx 0{,}29$</li></ol><div class=\"gans\"><b>Svar:</b> Å overse en syk pasient koster 12,48, så modellen lærer å prioritere å finne de syke.</div>","<div class=\"gset\">A disease model uses w₁ = 9 for sick and w₀ = 1 for healthy patients. A sick patient (y = 1) gets $y_{\\text{pred}} = 0.25$.</div><ol class=\"gsteps\"><li>Unweighted: $-\\ln 0.25 \\approx 1.386$</li><li>Weighted: $L = 9 \\cdot 1.386 \\approx 12.48$</li><li>Healthy patient with $y_{\\text{pred}} = 0.25$: $L = -1 \\cdot \\ln 0.75 \\approx 0.29$</li></ol><div class=\"gans\"><b>Answer:</b> Missing a sick patient costs 12.48, so the model learns to prioritise catching the sick.</div>"]},
 {id:"g-curse", n:["Dimensjonsforbannelsen","The curse of dimensionality"],
  f:["Bins totalt $= b^d$ &nbsp; ($b$ bins per akse, $d$ dimensjoner)<br>Underkube med andel $r$ av volumet i $[0, 1]^d$: sidekant $e = r^{1/d}$", "Total bins $= b^d$ &nbsp; ($b$ bins per axis, $d$ dimensions)<br>Sub-cube with share $r$ of the volume in $[0, 1]^d$: edge $e = r^{1/d}$"],
  e:["Antall datapunkter du trenger vokser eksponentielt med d. I høye dimensjoner blir alle avstander omtrent like store, og «lokale» naboer er ikke lenger lokale.","The number of data points you need grows exponentially with d. In high dimensions all distances become about equal, and “local” neighbours are no longer local."],
  ex:["<div class=\"gset\">Kundedata deles i 10 bins per feature, og vi vil ha 10 kunder per bin.</div><ol class=\"gsteps\"><li>$d = 1$: $10$ bins, $100$ kunder</li><li>$d = 3$: $10^3 = 1000$ bins, $10^4$ kunder</li><li>Et nabolag med 10 % av volumet i 10D: $e = 0{,}1^{1/10} \\approx 0{,}79$</li></ol><div class=\"gans\"><b>Svar:</b> Databehovet vokser med en faktor 10 per feature, og et «lokalt» 10 %-nabolag dekker 79 % av hver akse.</div>","<div class=\"gset\">Customer data are split into 10 bins per feature, and we want 10 customers per bin.</div><ol class=\"gsteps\"><li>$d = 1$: $10$ bins, $100$ customers</li><li>$d = 3$: $10^3 = 1000$ bins, $10^4$ customers</li><li>A neighbourhood with 10 % of the volume in 10D: $e = 0.1^{1/10} \\approx 0.79$</li></ol><div class=\"gans\"><b>Answer:</b> The data need grows by a factor 10 per feature, and a \"local\" 10 % neighbourhood spans 79 % of each axis.</div>"]}
]},
// ===== 4 Trees & ensembles =====
{t:4, items:[
 {id:"g-gini", n:["Gini-urenhet","Gini impurity"],
  f:["$\\text{Gini}(D) = 1 - \\sum_{i=1}^{k} p_i^2$", "$\\text{Gini}(D) = 1 - \\sum_{i=1}^{k} p_i^2$"],
  e:["Sannsynligheten for å klassifisere et tilfeldig punkt feil hvis du gjetter etter klassefordelingen i noden. For to klasser ligger den i [0, 0,5]: 0 er en ren node og 0,5 en jevn fordeling. Default i sklearn og billigere enn entropi.","The probability of misclassifying a random point if you guess according to the class distribution in the node. For two classes it lies in [0, 0.5]: 0 is a pure node and 0.5 an even split. The default in sklearn and cheaper than entropy."],
  ex:["<div class=\"gset\">Roten i et tre for lånesøknader har 50 tidligere lån: 30 tilbakebetalt og 20 misligholdt.</div><ol class=\"gsteps\"><li>$p_1 = \\frac{30}{50} = 0{,}6, \\quad p_2 = \\frac{20}{50} = 0{,}4$</li><li>$0{,}6^2 + 0{,}4^2 = 0{,}36 + 0{,}16 = 0{,}52$</li><li>$\\text{Gini} = 1 - 0{,}52 = 0{,}48$</li></ol><div class=\"gans\"><b>Svar:</b> 0,48 er nær maksimum 0,5 for to klasser, så roten er svært blandet og verdt å splitte.</div>","<div class=\"gset\">The root of a loan-approval tree holds 50 past loans: 30 repaid and 20 defaulted.</div><ol class=\"gsteps\"><li>$p_1 = \\frac{30}{50} = 0.6, \\quad p_2 = \\frac{20}{50} = 0.4$</li><li>$0.6^2 + 0.4^2 = 0.36 + 0.16 = 0.52$</li><li>$\\text{Gini} = 1 - 0.52 = 0.48$</li></ol><div class=\"gans\"><b>Answer:</b> 0.48 is close to the maximum 0.5 for two classes, so the root is very mixed and worth splitting.</div>"]},
 {id:"g-gini-split", n:["Gini etter en splitt","Gini after a split"],
  f:["$\\text{Gini}_f(D) = \\frac{n_1}{n} \\text{Gini}(D_1) + \\frac{n_2}{n} \\text{Gini}(D_2)$", "$\\text{Gini}_f(D) = \\frac{n_1}{n} \\text{Gini}(D_1) + \\frac{n_2}{n} \\text{Gini}(D_2)$"],
  e:["Vekt hvert barn med andelen punkter det får. Velg den featuren og verdien som gir <b>lavest</b> vektet urenhet. Et uvektet snitt er en vanlig feil.","Weight each child by the share of points it gets. Choose the feature and value with the <b>lowest</b> weighted impurity. An unweighted mean is a common mistake."],
  ex:["<div class=\"gset\">Et Titanic-tre splitter 200 passasjerer på kjønn: 120 menn (24 overlevde) og 80 kvinner (60 overlevde).</div><ol class=\"gsteps\"><li>Menn: $1 - 0{,}2^2 - 0{,}8^2 = 0{,}32$</li><li>Kvinner: $1 - 0{,}75^2 - 0{,}25^2 = 0{,}375$</li><li>$\\text{Gini}_f = \\frac{120}{200} \\cdot 0{,}32 + \\frac{80}{200} \\cdot 0{,}375 = 0{,}192 + 0{,}15 = 0{,}342$</li><li>Rot (84 av 200 overlevde): $1 - 0{,}42^2 - 0{,}58^2 \\approx 0{,}487$</li></ol><div class=\"gans\"><b>Svar:</b> Splitten senker urenheten fra 0,487 til 0,342, en god splittkandidat.</div>","<div class=\"gset\">A Titanic tree splits 200 passengers on sex: 120 men (24 survived) and 80 women (60 survived).</div><ol class=\"gsteps\"><li>Men: $1 - 0.2^2 - 0.8^2 = 0.32$</li><li>Women: $1 - 0.75^2 - 0.25^2 = 0.375$</li><li>$\\text{Gini}_f = \\frac{120}{200} \\cdot 0.32 + \\frac{80}{200} \\cdot 0.375 = 0.192 + 0.15 = 0.342$</li><li>Root (84 of 200 survived): $1 - 0.42^2 - 0.58^2 \\approx 0.487$</li></ol><div class=\"gans\"><b>Answer:</b> The split lowers the impurity from 0.487 to 0.342, a good split candidate.</div>"]},
 {id:"g-entropy", n:["Entropi","Entropy"],
  f:["$I(p_1, \\dots, p_k) = -\\sum_{i=1}^{k} p_i \\log_2(p_i)$", "$I(p_1, \\dots, p_k) = -\\sum_{i=1}^{k} p_i \\log_2(p_i)$"],
  e:["Usikkerheten i en fordeling. For to klasser er den 1 ved (0,5; 0,5) og 0 når alle er i samme klasse. Bruk log<sub>2</sub>, og 0·log 0 = 0.","The uncertainty in a distribution. For two classes it is 1 at (0.5, 0.5) and 0 when everything is in one class. Use log<sub>2</sub>, and 0·log 0 = 0."],
  ex:["<div class=\"gset\">En bank har 14 lånesøkere: 9 betalte tilbake (p) og 5 misligholdt (n).</div><ol class=\"gsteps\"><li>$\\frac{9}{14} \\approx 0{,}643, \\quad \\frac{5}{14} \\approx 0{,}357$</li><li>$-0{,}643 \\log_2 0{,}643 \\approx 0{,}410$</li><li>$-0{,}357 \\log_2 0{,}357 \\approx 0{,}530$</li><li>$I = 0{,}410 + 0{,}530 = 0{,}94$</li></ol><div class=\"gans\"><b>Svar:</b> 0,94 bit, nær maksimum 1, så utfallet er fortsatt svært usikkert.</div>","<div class=\"gset\">A bank has 14 loan applicants: 9 repaid (p) and 5 defaulted (n).</div><ol class=\"gsteps\"><li>$\\frac{9}{14} \\approx 0.643, \\quad \\frac{5}{14} \\approx 0.357$</li><li>$-0.643 \\log_2 0.643 \\approx 0.410$</li><li>$-0.357 \\log_2 0.357 \\approx 0.530$</li><li>$I = 0.410 + 0.530 = 0.94$</li></ol><div class=\"gans\"><b>Answer:</b> 0.94 bits, close to the maximum 1, so the outcome is still very uncertain.</div>"]},
 {id:"g-infogain", n:["Informasjonsgevinst","Information gain"],
  f:["$\\Delta I = I_{\\text{før}} - E[I_{\\text{etter}}]$<br>$E[I_{\\text{etter}}] = \\sum_{i=1}^{s} \\frac{p_i + n_i}{p + n}\\, I\\left(\\frac{p_i}{p_i + n_i}, \\frac{n_i}{p_i + n_i}\\right)$", "$\\Delta I = I_{\\text{before}} - E[I_{\\text{after}}]$<br>$E[I_{\\text{after}}] = \\sum_{i=1}^{s} \\frac{p_i + n_i}{p + n}\\, I\\left(\\frac{p_i}{p_i + n_i}, \\frac{n_i}{p_i + n_i}\\right)$"],
  e:["Hvor mye en splitt reduserer entropien. Velg splitten med <b>størst</b> ΔI. Barna vektes med sin andel av punktene.","How much a split reduces the entropy. Choose the split with the <b>largest</b> ΔI. The children are weighted by their share of the points."],
  ex:["<div class=\"gset\">De 14 lånesøkerne [9 betalte, 5 misligholdt] splittes på fast jobb: uten [4, 5], med [5, 0].</div><ol class=\"gsteps\"><li>Uten jobb: $I\\left(\\frac{4}{9}, \\frac{5}{9}\\right) \\approx 0{,}991$; med jobb: $I(1, 0) = 0$</li><li>$E[I_{\\text{etter}}] = \\frac{9}{14} \\cdot 0{,}991 + \\frac{5}{14} \\cdot 0 \\approx 0{,}637$</li><li>$\\Delta I = 0{,}940 - 0{,}637 \\approx 0{,}30$</li></ol><div class=\"gans\"><b>Svar:</b> Splitten gir 0,30 bit; gir ingen annen feature mer, splitter treet på fast jobb først.</div>","<div class=\"gset\">The 14 loan applicants [9 repaid, 5 defaulted] are split on permanent job: without [4, 5], with [5, 0].</div><ol class=\"gsteps\"><li>Without job: $I\\left(\\frac{4}{9}, \\frac{5}{9}\\right) \\approx 0.991$; with job: $I(1, 0) = 0$</li><li>$E[I_{\\text{after}}] = \\frac{9}{14} \\cdot 0.991 + \\frac{5}{14} \\cdot 0 \\approx 0.637$</li><li>$\\Delta I = 0.940 - 0.637 \\approx 0.30$</li></ol><div class=\"gans\"><b>Answer:</b> The split gains 0.30 bits; if no other feature gains more, the tree splits on permanent job first.</div>"]},
 {id:"g-regtree", n:["Splitt i regresjonstrær","Splits in regression trees"],
  f:["$\\text{Var}(D) = \\frac{1}{n} \\sum (y - \\bar{y})^2$<br>$\\text{Var}_{\\text{splitt}} = \\frac{n_1}{n} \\text{Var}(D_1) + \\frac{n_2}{n} \\text{Var}(D_2)$ &nbsp;·&nbsp; løvnoden predikerer $\\bar{y}$", "$\\text{Var}(D) = \\frac{1}{n} \\sum (y - \\bar{y})^2$<br>$\\text{Var}_{\\text{split}} = \\frac{n_1}{n} \\text{Var}(D_1) + \\frac{n_2}{n} \\text{Var}(D_2)$ &nbsp;·&nbsp; a leaf predicts $\\bar{y}$"],
  e:["Regresjonstrær velger splitten som gir lavest (vektet) varians, altså lavest MSE, i barna. Hver løvnode predikerer snittet av targets i sin region. Et binært tre med dybde d har høyst 2<sup>d</sup> løvnoder.","Regression trees choose the split that gives the lowest (weighted) variance, i.e. the lowest MSE, in the children. Each leaf predicts the mean of the targets in its region. A binary tree of depth d has at most 2<sup>d</sup> leaves."],
  ex:["<div class=\"gset\">Et regresjonstre splitter seks boligpriser (i millioner) på boareal: små boliger {1, 2, 3}, store boliger {10, 11, 12}.</div><ol class=\"gsteps\"><li>Snitt: $\\bar{y}_1 = 2, \\quad \\bar{y}_2 = 11$</li><li>$\\text{Var}(D_1) = \\frac{1 + 0 + 1}{3} = \\frac{2}{3}, \\quad \\text{Var}(D_2) = \\frac{2}{3}$</li><li>$\\frac{3}{6} \\cdot \\frac{2}{3} + \\frac{3}{6} \\cdot \\frac{2}{3} \\approx 0{,}67$</li><li>Før splitten: $\\bar{y} = 6{,}5$, $\\text{Var}(D) \\approx 20{,}92$</li></ol><div class=\"gans\"><b>Svar:</b> Splitten kutter variansen fra 20,92 til 0,67, og de to løvnodene predikerer 2 og 11 millioner.</div>","<div class=\"gset\">A regression tree splits six house prices (in millions) on floor area: small houses {1, 2, 3}, large houses {10, 11, 12}.</div><ol class=\"gsteps\"><li>Means: $\\bar{y}_1 = 2, \\quad \\bar{y}_2 = 11$</li><li>$\\text{Var}(D_1) = \\frac{1 + 0 + 1}{3} = \\frac{2}{3}, \\quad \\text{Var}(D_2) = \\frac{2}{3}$</li><li>$\\frac{3}{6} \\cdot \\frac{2}{3} + \\frac{3}{6} \\cdot \\frac{2}{3} \\approx 0.67$</li><li>Before the split: $\\bar{y} = 6.5$, $\\text{Var}(D) \\approx 20.92$</li></ol><div class=\"gans\"><b>Answer:</b> The split cuts the variance from 20.92 to 0.67, and the two leaves predict 2 and 11 million.</div>"]},
 {id:"g-oob", n:["Bootstrap og out-of-bag","Bootstrap and out-of-bag"],
  f:["$P(\\text{out-of-bag}) = \\left(1 - \\frac{1}{n}\\right)^n \\to \\frac{1}{e} \\approx 0{,}368$ når $n \\to \\infty$", "$P(\\text{out-of-bag}) = \\left(1 - \\frac{1}{n}\\right)^n \\to \\frac{1}{e} \\approx 0.368$ as $n \\to \\infty$"],
  e:["I bagging trekkes n punkter <i>med tilbakelegging</i>. Hvert punkt har sannsynlighet 1 − 1/n for ikke å bli trukket i én trekning. Omtrent 37 % havner utenfor (out-of-bag) og kan brukes til validering.","In bagging, n points are drawn <i>with replacement</i>. Each point has probability 1 − 1/n of not being drawn in one draw. About 37 % end up out-of-bag and can be used for validation."],
  ex:["<div class=\"gset\">En random forest trener hvert tre på et bootstrap-utvalg av 10 pasienter.</div><ol class=\"gsteps\"><li>Én trekning bommer på en gitt pasient: $1 - \\frac{1}{10} = 0{,}9$</li><li>Alle 10 trekningene bommer: $0{,}9^{10} \\approx 0{,}349$</li><li>Forventet out-of-bag: $10 \\cdot 0{,}349 \\approx 3{,}5$ pasienter</li></ol><div class=\"gans\"><b>Svar:</b> Omtrent 34,9 % (3–4 pasienter) er usett av hvert tre og kan validere det; for stor n går dette mot 36,8 %.</div>","<div class=\"gset\">A random forest trains each tree on a bootstrap sample of 10 patients.</div><ol class=\"gsteps\"><li>One draw misses a given patient: $1 - \\frac{1}{10} = 0.9$</li><li>All 10 draws miss: $0.9^{10} \\approx 0.349$</li><li>Expected out-of-bag: $10 \\cdot 0.349 \\approx 3.5$ patients</li></ol><div class=\"gans\"><b>Answer:</b> About 34.9 % (3–4 patients) are unseen by each tree and can validate it; for large n this tends to 36.8 %.</div>"]},
 {id:"g-adaboost", n:["AdaBoost: vekt per modell","AdaBoost: weight per model"],
  f:["$\\alpha = \\frac{1}{2} \\ln\\frac{1 - \\varepsilon}{\\varepsilon}$", "$\\alpha = \\frac{1}{2} \\ln\\frac{1 - \\varepsilon}{\\varepsilon}$"],
  e:["ε er den vektede feilraten til den svake modellen. Lav feil gir stor α (modellen stemmer tyngre), og ε = 0,5 gir α = 0. Feilklassifiserte punkter får økt vekt til neste modell, så modellene trenes sekvensielt.","ε is the weak model's weighted error rate. A low error gives a large α (the model's vote counts more), and ε = 0.5 gives α = 0. Misclassified points get a higher weight for the next model, so the models are trained sequentially."],
  ex:["<div class=\"gset\">AdaBoost i et spamfilter: den første stubben har vektet feil ε = 0,2, den andre ε = 0,4.</div><ol class=\"gsteps\"><li>$\\frac{1 - 0{,}2}{0{,}2} = 4, \\quad \\alpha_1 = \\frac{1}{2} \\ln 4 \\approx 0{,}69$</li><li>$\\frac{1 - 0{,}4}{0{,}4} = 1{,}5, \\quad \\alpha_2 = \\frac{1}{2} \\ln 1{,}5 \\approx 0{,}20$</li><li>Forhold: $\\frac{0{,}69}{0{,}20} \\approx 3{,}4$</li></ol><div class=\"gans\"><b>Svar:</b> Stemmen til den første stubben teller omtrent 3,4 ganger så mye som den andre sin.</div>","<div class=\"gset\">AdaBoost for a spam filter: the first stump has weighted error ε = 0.2, the second ε = 0.4.</div><ol class=\"gsteps\"><li>$\\frac{1 - 0.2}{0.2} = 4, \\quad \\alpha_1 = \\frac{1}{2} \\ln 4 \\approx 0.69$</li><li>$\\frac{1 - 0.4}{0.4} = 1.5, \\quad \\alpha_2 = \\frac{1}{2} \\ln 1.5 \\approx 0.20$</li><li>Ratio: $\\frac{0.69}{0.20} \\approx 3.4$</li></ol><div class=\"gans\"><b>Answer:</b> The first stump's vote counts about 3.4 times as much as the second one's.</div>"]},
 {id:"g-gboost", n:["Gradient boosting","Gradient boosting"],
  f:["Pseudo-residual: $g = -(y - F(x))$<br>$\\text{new\\_ensemble} = \\text{previous\\_ensemble} - \\text{learning\\_rate} \\cdot \\text{new\\_tree}$ &nbsp; ($\\text{new\\_tree}$ tilpasses $g$)", "Pseudo-residual: $g = -(y - F(x))$<br>$\\text{new\\_ensemble} = \\text{previous\\_ensemble} - \\text{learning\\_rate} \\cdot \\text{new\\_tree}$ &nbsp; ($\\text{new\\_tree}$ is fitted to $g$)"],
  e:["Hvert nye tre predikerer feilen til forrige ensemble, og ensemblet tar et lite steg mot target. Det er gradient descent i rommet av trær. AdaBoost vekter i stedet datapunkter.","Each new tree predicts the error of the previous ensemble, and the ensemble takes a small step towards the target. It is gradient descent in the space of trees. AdaBoost weights data points instead."],
  ex:["<div class=\"gset\">Gradient boosting for boligpriser: en bolig koster y = 10 (millioner), nåværende ensemble predikerer F = 6, læringsrate 0,1.</div><ol class=\"gsteps\"><li>$g = -(y - F) = -(10 - 6) = -4$</li><li>Det nye treet tilpasses $g$ og predikerer $-4$ her</li><li>$F_{\\text{ny}} = 6 - 0{,}1 \\cdot (-4) = 6{,}4$</li><li>Gjenstående feil: $10 - 6{,}4 = 3{,}6$</li></ol><div class=\"gans\"><b>Svar:</b> Prediksjonen tar et lite steg fra 6 til 6,4 millioner; senere trær fortsetter å tette gapet.</div>","<div class=\"gset\">Gradient boosting for house prices: a house costs y = 10 (millions), the current ensemble predicts F = 6, learning rate 0.1.</div><ol class=\"gsteps\"><li>$g = -(y - F) = -(10 - 6) = -4$</li><li>The new tree is fitted to $g$ and predicts $-4$ here</li><li>$F_{\\text{new}} = 6 - 0.1 \\cdot (-4) = 6.4$</li><li>Remaining error: $10 - 6.4 = 3.6$</li></ol><div class=\"gans\"><b>Answer:</b> The prediction moves a small step from 6 to 6.4 million; later trees keep closing the gap.</div>"]}
]},
// ===== 5 Regression, bias/variance & validation =====
{t:5, items:[
 {id:"g-linreg", n:["Lineær regresjon","Linear regression"],
  f:["$f(x) = \\beta_0 + \\beta_1 x_1 + \\dots + \\beta_n x_n$ &nbsp;·&nbsp; $n + 1$ parametre", "$f(x) = \\beta_0 + \\beta_1 x_1 + \\dots + \\beta_n x_n$ &nbsp;·&nbsp; $n + 1$ parameters"],
  e:["β<sub>0</sub> er biasen (verdien ved x = 0) og β<sub>i</sub> stigningstallene. Polynomisk regresjon er fortsatt lineær i parametrene: f(x) = β<sub>0</sub> + β<sub>1</sub>x + … + β<sub>M</sub>x<sup>M</sup>, med genererte features.","β<sub>0</sub> is the bias (the value at x = 0) and β<sub>i</sub> are the slopes. Polynomial regression is still linear in the parameters: f(x) = β<sub>0</sub> + β<sub>1</sub>x + … + β<sub>M</sub>x<sup>M</sup>, with generated features."],
  ex:["<div class=\"gset\">En boligprismodell (millioner) er f(x) = 0,5 + 0,03·areal + 0,2·soverom. En bolig har 100 m² og 3 soverom.</div><ol class=\"gsteps\"><li>$\\beta_1 x_1 = 0{,}03 \\cdot 100 = 3$</li><li>$\\beta_2 x_2 = 0{,}2 \\cdot 3 = 0{,}6$</li><li>$f(x) = 0{,}5 + 3 + 0{,}6 = 4{,}1$</li><li>Parametre: $n + 1 = 2 + 1 = 3$</li></ol><div class=\"gans\"><b>Svar:</b> Predikert pris er 4,1 millioner; hver ekstra m² legger til 0,03 millioner (30 000).</div>","<div class=\"gset\">A house-price model (millions) is f(x) = 0.5 + 0.03·area + 0.2·bedrooms. A house has 100 m² and 3 bedrooms.</div><ol class=\"gsteps\"><li>$\\beta_1 x_1 = 0.03 \\cdot 100 = 3$</li><li>$\\beta_2 x_2 = 0.2 \\cdot 3 = 0.6$</li><li>$f(x) = 0.5 + 3 + 0.6 = 4.1$</li><li>Parameters: $n + 1 = 2 + 1 = 3$</li></ol><div class=\"gans\"><b>Answer:</b> The predicted price is 4.1 million; each extra m² adds 0.03 million (30 000).</div>"]},
 {id:"g-mse", n:["Mean squared error","Mean squared error"],
  f:["Notatene: $\\text{MSE} = \\frac{1}{2N} \\sum_i \\left(y^{(i)} - f(x^{(i)})\\right)^2$<br>Vanlig (sklearn): $\\text{MSE} = \\frac{1}{N} \\sum_i \\left(y^{(i)} - \\hat{y}^{(i)}\\right)^2$", "The notes: $\\text{MSE} = \\frac{1}{2N} \\sum_i \\left(y^{(i)} - f(x^{(i)})\\right)^2$<br>Common (sklearn): $\\text{MSE} = \\frac{1}{N} \\sum_i \\left(y^{(i)} - \\hat{y}^{(i)}\\right)^2$"],
  e:["Faktoren ½ er bare for bekvemmelighet: den forsvinner når du deriverer. Les oppgaven nøye for å se hvilken definisjon som brukes. Minimere MSE tilsvarer å maksimere likelihood under Gaussisk støy.","The factor ½ is only for convenience: it cancels when you differentiate. Read the question carefully to see which definition is used. Minimising MSE is the same as maximising the likelihood under Gaussian noise."],
  ex:["<div class=\"gset\">En modell predikerer fire boligpriser (millioner): y = [3, 5, 2, 7], ŷ = [2, 5, 4, 6].</div><ol class=\"gsteps\"><li>Feil $y - \\hat{y}$: $1, 0, -2, 1$</li><li>$SSE = 1 + 0 + 4 + 1 = 6$</li><li>sklearn: $\\text{MSE} = \\frac{6}{4} = 1{,}5$</li><li>Notatene: $\\text{MSE} = \\frac{6}{2 \\cdot 4} = 0{,}75$</li></ol><div class=\"gans\"><b>Svar:</b> MSE = 1,5 (eller 0,75 med ½-konvensjonen); den ene feilen på 2 står for 4 av de 6.</div>","<div class=\"gset\">A model predicts four house prices (millions): y = [3, 5, 2, 7], ŷ = [2, 5, 4, 6].</div><ol class=\"gsteps\"><li>Errors $y - \\hat{y}$: $1, 0, -2, 1$</li><li>$SSE = 1 + 0 + 4 + 1 = 6$</li><li>sklearn: $\\text{MSE} = \\frac{6}{4} = 1.5$</li><li>The notes: $\\text{MSE} = \\frac{6}{2 \\cdot 4} = 0.75$</li></ol><div class=\"gans\"><b>Answer:</b> MSE = 1.5 (or 0.75 with the ½ convention); the single error of 2 contributes 4 of the 6.</div>"]},
 {id:"g-linreg-gd", n:["Gradient descent for lineær regresjon","Gradient descent for linear regression"],
  f:["$\\beta_0 \\leftarrow \\beta_0 - \\eta \\frac{1}{N} \\sum_i \\left(f(x^{(i)}) - y^{(i)}\\right)$<br>$\\beta_1 \\leftarrow \\beta_1 - \\eta \\frac{1}{N} \\sum_i x^{(i)} \\left(f(x^{(i)}) - y^{(i)}\\right)$", "$\\beta_0 \\leftarrow \\beta_0 - \\eta \\frac{1}{N} \\sum_i \\left(f(x^{(i)}) - y^{(i)}\\right)$<br>$\\beta_1 \\leftarrow \\beta_1 - \\eta \\frac{1}{N} \\sum_i x^{(i)} \\left(f(x^{(i)}) - y^{(i)}\\right)$"],
  e:["Fra den deriverte av MSE med faktor ½. Hvis modellen overestimerer overalt, er ∂L/∂β<sub>0</sub> > 0, så β<sub>0</sub> minker.","From the derivative of MSE with the factor ½. If the model overestimates everywhere, ∂L/∂β<sub>0</sub> > 0, so β<sub>0</sub> decreases."],
  ex:["<div class=\"gset\">Lønn mot års erfaring: punktene (1, 3) og (2, 5). Start med β = (0, 1), η = 0,1.</div><ol class=\"gsteps\"><li>Prediksjoner $f = 1, 2$; feil $f - y = -2, -3$</li><li>$\\beta_0 = 0 - 0{,}1 \\cdot \\frac{-2 - 3}{2} = 0 + 0{,}25 = 0{,}25$</li><li>$\\beta_1 = 1 - 0{,}1 \\cdot \\frac{1 \\cdot (-2) + 2 \\cdot (-3)}{2} = 1 + 0{,}4 = 1{,}4$</li></ol><div class=\"gans\"><b>Svar:</b> Etter ett steg er β = (0,25, 1,4); modellen underestimerte, så begge parametrene økte.</div>","<div class=\"gset\">Salary vs years of experience: points (1, 3) and (2, 5). Start with β = (0, 1), η = 0.1.</div><ol class=\"gsteps\"><li>Predictions $f = 1, 2$; errors $f - y = -2, -3$</li><li>$\\beta_0 = 0 - 0.1 \\cdot \\frac{-2 - 3}{2} = 0 + 0.25 = 0.25$</li><li>$\\beta_1 = 1 - 0.1 \\cdot \\frac{1 \\cdot (-2) + 2 \\cdot (-3)}{2} = 1 + 0.4 = 1.4$</li></ol><div class=\"gans\"><b>Answer:</b> After one step β = (0.25, 1.4); the model underestimated, so both parameters went up.</div>"]},
 {id:"g-r2", n:["R² (forklaringsgrad)","R² (coefficient of determination)"],
  f:["$R^2 = 1 - \\frac{SSE}{SST}$<br>$SSE = \\sum (y - \\hat{y})^2 \\qquad SST = \\sum (y - \\bar{y})^2$", "$R^2 = 1 - \\frac{SSE}{SST}$<br>$SSE = \\sum (y - \\hat{y})^2 \\qquad SST = \\sum (y - \\bar{y})^2$"],
  e:["Andelen av variansen i y som modellen forklarer. 1 er perfekt, 0 er like godt som å alltid predikere ȳ, og negativ er dårligere enn det.","The share of the variance in y that the model explains. 1 is perfect, 0 is as good as always predicting ȳ, and negative is worse than that."],
  ex:["<div class=\"gset\">En modell predikerer leveringstid (dager) for fire pakker: y = [2, 4, 6, 8], ŷ = [3, 4, 5, 8].</div><ol class=\"gsteps\"><li>$\\bar{y} = \\frac{2 + 4 + 6 + 8}{4} = 5$</li><li>$SST = 9 + 1 + 1 + 9 = 20$</li><li>$SSE = 1 + 0 + 1 + 0 = 2$</li><li>$R^2 = 1 - \\frac{2}{20} = 0{,}9$</li></ol><div class=\"gans\"><b>Svar:</b> Modellen forklarer 90 % av variasjonen i leveringstid.</div>","<div class=\"gset\">A model predicts delivery times (days) for four parcels: y = [2, 4, 6, 8], ŷ = [3, 4, 5, 8].</div><ol class=\"gsteps\"><li>$\\bar{y} = \\frac{2 + 4 + 6 + 8}{4} = 5$</li><li>$SST = 9 + 1 + 1 + 9 = 20$</li><li>$SSE = 1 + 0 + 1 + 0 = 2$</li><li>$R^2 = 1 - \\frac{2}{20} = 0.9$</li></ol><div class=\"gans\"><b>Answer:</b> The model explains 90 % of the variation in delivery time.</div>"]},
 {id:"g-biasvar", n:["Bias–varians-dekomposisjonen","The bias–variance decomposition"],
  f:["$E_D\\left[(y - f(x; D))^2\\right] = \\left(\\text{Bias}_D[f(x; D)]\\right)^2 + \\text{Var}_D[f(x; D)] + \\sigma^2$<br>$\\text{Bias}_D = E_D[f(x; D)] - F(x) \\qquad \\text{Var}_D = E_D\\left[\\left(E_D[f(x; D)] - f(x; D)\\right)^2\\right]$", "$E_D\\left[(y - f(x; D))^2\\right] = \\left(\\text{Bias}_D[f(x; D)]\\right)^2 + \\text{Var}_D[f(x; D)] + \\sigma^2$<br>$\\text{Bias}_D = E_D[f(x; D)] - F(x) \\qquad \\text{Var}_D = E_D\\left[\\left(E_D[f(x; D)] - f(x; D)\\right)^2\\right]$"],
  e:["Forventet feil på et nytt punkt = bias² (systematisk bom, undertilpasning) + varians (sensitivitet for treningsutvalget, overtilpasning) + irredusibel støy σ². Mer kompleksitet gir lavere bias og høyere varians.","The expected error on a new point = bias² (systematic miss, underfitting) + variance (sensitivity to the training sample, overfitting) + irreducible noise σ². More complexity gives lower bias and higher variance."],
  ex:["<div class=\"gset\">En modell predikerer høyde. For én person er sann F(x) = 167 cm; over mange treningssett er snittprediksjonen 165 cm med varians 3 cm², og støyen er σ² = 1 cm².</div><ol class=\"gsteps\"><li>$\\text{Bias} = 165 - 167 = -2$</li><li>$\\text{Bias}^2 = 4$</li><li>$E[\\text{feil}] = 4 + 3 + 1 = 8 \\text{ cm}^2$</li></ol><div class=\"gans\"><b>Svar:</b> Forventet kvadratfeil er 8 cm²; halvparten er bias, så en mer fleksibel modell kan hjelpe.</div>","<div class=\"gset\">A model predicts adult height. For one person the true F(x) = 167 cm; over many training sets the mean prediction is 165 cm with variance 3 cm², and the noise is σ² = 1 cm².</div><ol class=\"gsteps\"><li>$\\text{Bias} = 165 - 167 = -2$</li><li>$\\text{Bias}^2 = 4$</li><li>$E[\\text{error}] = 4 + 3 + 1 = 8 \\text{ cm}^2$</li></ol><div class=\"gans\"><b>Answer:</b> Expected squared error 8 cm²; half of it is bias, so a more flexible model could help.</div>"]},
 {id:"g-polyfeat", n:["Antall polynomfeatures","Number of polynomial features"],
  f:["Antall monomer av grad $\\le p$ i $d$ variabler $= \\binom{d + p}{p} = \\frac{(d + p)!}{d!\\, p!}$", "Number of monomials of degree $\\le p$ in $d$ variables $= \\binom{d + p}{p} = \\frac{(d + p)!}{d!\\, p!}$"],
  e:["Inkluderer konstantleddet og alle kryssledd (<code>PolynomialFeatures</code>). Graden p er en hyperparameter, og antallet vokser raskt med d og p.","Includes the constant term and all cross terms (<code>PolynomialFeatures</code>). The degree p is a hyperparameter, and the count grows quickly with d and p."],
  ex:["<div class=\"gset\">En boligprismodell har d = 3 features (areal, alder, avstand) og bruker <code>PolynomialFeatures(degree=2)</code>.</div><ol class=\"gsteps\"><li>$\\binom{3 + 2}{2} = \\frac{5!}{3!\\, 2!} = 10$</li><li>Sjekk: $1$ konstant $+ 3$ lineære $+ 3$ kvadrater $+ 3$ kryssledd $= 10$</li><li>Grad 3: $\\binom{6}{3} = 20$</li></ol><div class=\"gans\"><b>Svar:</b> Modellen får 10 features med grad 2 og allerede 20 med grad 3.</div>","<div class=\"gset\">A house-price model has d = 3 features (area, age, distance) and uses <code>PolynomialFeatures(degree=2)</code>.</div><ol class=\"gsteps\"><li>$\\binom{3 + 2}{2} = \\frac{5!}{3!\\, 2!} = 10$</li><li>Check: $1$ constant $+ 3$ linear $+ 3$ squares $+ 3$ cross terms $= 10$</li><li>Degree 3: $\\binom{6}{3} = 20$</li></ol><div class=\"gans\"><b>Answer:</b> The model gets 10 features at degree 2 and already 20 at degree 3.</div>"]},
 {id:"g-cv", n:["Kryssvalidering","Cross-validation"],
  f:["k-fold: $k$ tilpasninger, hver trent på $\\frac{n(k-1)}{k}$ og testet på $\\frac{n}{k}$<br>LOOCV: $n$ tilpasninger, hver trent på $n - 1$ og testet på 1", "k-fold: $k$ fits, each trained on $\\frac{n(k-1)}{k}$ and tested on $\\frac{n}{k}$<br>LOOCV: $n$ fits, each trained on $n - 1$ and tested on 1"],
  e:["Hver del er test (validering) én gang, og estimatet er snittet av de k resultatene. LOOCV bruker dataene best, men er dyr. k-fold er en billigere mellomting.","Each part is the test (validation) set once, and the estimate is the mean of the k results. LOOCV uses the data best, but is expensive. k-fold is a cheaper compromise."],
  ex:["<div class=\"gset\">En churn-modell evalueres på 1000 kunder med 5-fold kryssvalidering.</div><ol class=\"gsteps\"><li>Hver fold: $\\frac{1000}{5} = 200$ valideringskunder</li><li>Trening: $\\frac{1000 \\cdot 4}{5} = 800$, og $5$ tilpasninger</li><li>LOOCV i stedet: $1000$ tilpasninger på $999$ hver</li></ol><div class=\"gans\"><b>Svar:</b> 5-fold trener 5 modeller på 800 kunder hver; LOOCV ville krevd 1000 tilpasninger.</div>","<div class=\"gset\">A churn model is evaluated on 1000 customers with 5-fold cross-validation.</div><ol class=\"gsteps\"><li>Each fold: $\\frac{1000}{5} = 200$ validation customers</li><li>Training: $\\frac{1000 \\cdot 4}{5} = 800$, and $5$ fits</li><li>LOOCV instead: $1000$ fits on $999$ each</li></ol><div class=\"gans\"><b>Answer:</b> 5-fold trains 5 models on 800 customers each; LOOCV would need 1000 fits.</div>"]}
]},
// ===== 6 Neural networks =====
{t:6, items:[
 {id:"g-perceptron", n:["Perceptron","Perceptron"],
  f:["$\\hat{y} = H(\\mathbf{w}\\cdot\\mathbf{x} + b)$, der $H(z) = 1$ hvis $z \\ge 0$, ellers 0<br>Læringsregel: $w_i \\leftarrow w_i + \\eta\\, (y - \\hat{y})\\, x_i \\qquad b \\leftarrow b + \\eta\\, (y - \\hat{y})$", "$\\hat{y} = H(\\mathbf{w}\\cdot\\mathbf{x} + b)$, where $H(z) = 1$ if $z \\ge 0$, else 0<br>Learning rule: $w_i \\leftarrow w_i + \\eta\\, (y - \\hat{y})\\, x_i \\qquad b \\leftarrow b + \\eta\\, (y - \\hat{y})$"],
  e:["Én node med stegfunksjon gir en lineær beslutningsgrense, så XOR er umulig. Vektene endres bare når prediksjonen er feil. Eksempler: AND = (1, 1, −1,5), OR = (1, 1, −0,5), NOT = (−1, 0,5).","A single unit with a step function gives a linear decision boundary, so XOR is impossible. The weights only change when the prediction is wrong. Examples: AND = (1, 1, −1.5), OR = (1, 1, −0.5), NOT = (−1, 0.5)."],
  ex:["<div class=\"gset\">En perceptron godkjenner lån ut fra x = (har jobb, har gjeld) = (1, 1). Nå er w = (0,2, −0,4), b = 0,1, η = 0,5, og sann label er y = 1.</div><ol class=\"gsteps\"><li>$z = 0{,}2 - 0{,}4 + 0{,}1 = -0{,}1 < 0 \\;\\Rightarrow\\; \\hat{y} = 0$</li><li>$y - \\hat{y} = 1, \\quad \\eta\\,(y - \\hat{y}) = 0{,}5$</li><li>$w = (0{,}2 + 0{,}5,\\ -0{,}4 + 0{,}5) = (0{,}7,\\ 0{,}1), \\quad b = 0{,}6$</li></ol><div class=\"gans\"><b>Svar:</b> Det feilaktige avslaget flytter vektene slik at z = 1,4 neste gang, og lånet godkjennes.</div>","<div class=\"gset\">A perceptron approves loans from x = (has job, has debt) = (1, 1). Now w = (0.2, −0.4), b = 0.1, η = 0.5, and the true label is y = 1.</div><ol class=\"gsteps\"><li>$z = 0.2 - 0.4 + 0.1 = -0.1 < 0 \\;\\Rightarrow\\; \\hat{y} = 0$</li><li>$y - \\hat{y} = 1, \\quad \\eta\\,(y - \\hat{y}) = 0.5$</li><li>$w = (0.2 + 0.5,\\ -0.4 + 0.5) = (0.7,\\ 0.1), \\quad b = 0.6$</li></ol><div class=\"gans\"><b>Answer:</b> The wrong rejection moves the weights so that z = 1.4 next time, and the loan is approved.</div>"]},
 {id:"g-neuron", n:["Aktivering i en node","The activation of a unit"],
  f:["$a_j = g\\left(\\sum_i w_{ij}\\, a_i + b_j\\right)$", "$a_j = g\\left(\\sum_i w_{ij}\\, a_i + b_j\\right)$"],
  e:["w<sub>ij</sub> er vekten fra node i i forrige lag til node j, og g er aktiveringsfunksjonen. Regn lag for lag (forward pass). Uten ikke-lineær g blir hele nettverket lineært.","w<sub>ij</sub> is the weight from unit i in the previous layer to unit j, and g is the activation function. Compute layer by layer (forward pass). Without a non-linear g the whole network is linear."],
  ex:["<div class=\"gset\">En skjult node i en bildeklassifiserer får input x = [2, 1, 0,5] med vekter w = [0,5, −1, 2], b = −0,5 og sigmoid.</div><ol class=\"gsteps\"><li>$\\sum_i w_i x_i = 1 - 1 + 1 = 1$</li><li>$z = 1 - 0{,}5 = 0{,}5$</li><li>$a = \\sigma(0{,}5) = \\frac{1}{1 + e^{-0{,}5}} \\approx 0{,}62$</li></ol><div class=\"gans\"><b>Svar:</b> Noden gir ut 0,62, som sendes videre som input til neste lag.</div>","<div class=\"gset\">A hidden unit in an image classifier gets inputs x = [2, 1, 0.5] with weights w = [0.5, −1, 2], b = −0.5 and sigmoid.</div><ol class=\"gsteps\"><li>$\\sum_i w_i x_i = 1 - 1 + 1 = 1$</li><li>$z = 1 - 0.5 = 0.5$</li><li>$a = \\sigma(0.5) = \\frac{1}{1 + e^{-0.5}} \\approx 0.62$</li></ol><div class=\"gans\"><b>Answer:</b> The unit outputs 0.62, which is passed on as input to the next layer.</div>"]},
 {id:"g-activations", n:["Aktiveringsfunksjoner","Activation functions"],
  f:["$\\sigma(x) = \\frac{1}{1 + e^{-x}} \\qquad \\tanh(x) \\in (-1, 1) \\qquad \\text{ReLU}(x) = \\max(0, x)$<br>leaky ReLU: $x$ hvis $x > 0$, ellers $0{,}1 \\cdot x$", "$\\sigma(x) = \\frac{1}{1 + e^{-x}} \\qquad \\tanh(x) \\in (-1, 1) \\qquad \\text{ReLU}(x) = \\max(0, x)$<br>leaky ReLU: $x$ if $x > 0$, else $0.1 \\cdot x$"],
  e:["Sigmoid gir (0, 1) og passer i utgangen ved binær klassifisering. ReLU er standard i skjulte lag, billig og uten metning for x > 0, men kan gi «døde» noder. Stegfunksjonen har deriverte 0 og kan ikke trenes med backpropagation.","Sigmoid gives (0, 1) and suits the output for binary classification. ReLU is the default in hidden layers, cheap and without saturation for x > 0, but can give “dead” units. The step function has derivative 0 and cannot be trained with backpropagation."],
  ex:["<div class=\"gset\">En skjult node i en bildeklassifiserer får z = −2. Sammenlign aktiveringsfunksjonene.</div><ol class=\"gsteps\"><li>$\\sigma(-2) = \\frac{1}{1 + e^{2}} \\approx 0{,}12$</li><li>$\\tanh(-2) \\approx -0{,}96$</li><li>$\\text{ReLU}(-2) = \\max(0, -2) = 0$</li><li>$\\text{leaky ReLU}(-2) = 0{,}1 \\cdot (-2) = -0{,}2$</li></ol><div class=\"gans\"><b>Svar:</b> ReLU gir 0 med gradient 0 her (fare for en død node), mens leaky ReLU beholder en liten gradient på 0,1.</div>","<div class=\"gset\">A hidden unit in an image classifier receives z = −2. Compare the activation functions.</div><ol class=\"gsteps\"><li>$\\sigma(-2) = \\frac{1}{1 + e^{2}} \\approx 0.12$</li><li>$\\tanh(-2) \\approx -0.96$</li><li>$\\text{ReLU}(-2) = \\max(0, -2) = 0$</li><li>$\\text{leaky ReLU}(-2) = 0.1 \\cdot (-2) = -0.2$</li></ol><div class=\"gans\"><b>Answer:</b> ReLU outputs 0 with gradient 0 here (a risk of a dead unit), while leaky ReLU keeps a small gradient of 0.1.</div>"]},
 {id:"g-softmax", n:["Softmax","Softmax"],
  f:["$\\text{softmax}(z)_i = \\frac{e^{z_i}}{\\sum_j e^{z_j}}$", "$\\text{softmax}(z)_i = \\frac{e^{z_i}}{\\sum_j e^{z_j}}$"],
  e:["Gjør logits om til en sannsynlighetsfordeling over klassene (positiv, summerer til 1). Brukes i utgangslaget ved flerklasse-klassifisering.","Turns logits into a probability distribution over the classes (positive, sums to 1). Used in the output layer for multi-class classification."],
  ex:["<div class=\"gset\">En bildeklassifiserer gir logits z = [2, 1, 0] for katt, hund og fugl.</div><ol class=\"gsteps\"><li>$e^2 \\approx 7{,}39, \\quad e^1 \\approx 2{,}72, \\quad e^0 = 1$</li><li>Sum: $7{,}39 + 2{,}72 + 1 = 11{,}11$</li><li>$p = \\left(\\frac{7{,}39}{11{,}11}, \\frac{2{,}72}{11{,}11}, \\frac{1}{11{,}11}\\right) \\approx (0{,}67, 0{,}24, 0{,}09)$</li></ol><div class=\"gans\"><b>Svar:</b> Modellen sier katt med sannsynlighet 0,67, og de tre sannsynlighetene summerer til 1.</div>","<div class=\"gset\">An image classifier outputs logits z = [2, 1, 0] for cat, dog and bird.</div><ol class=\"gsteps\"><li>$e^2 \\approx 7.39, \\quad e^1 \\approx 2.72, \\quad e^0 = 1$</li><li>Sum: $7.39 + 2.72 + 1 = 11.11$</li><li>$p = \\left(\\frac{7.39}{11.11}, \\frac{2.72}{11.11}, \\frac{1}{11.11}\\right) \\approx (0.67, 0.24, 0.09)$</li></ol><div class=\"gans\"><b>Answer:</b> The model says cat with probability 0.67, and the three probabilities sum to 1.</div>"]},
 {id:"g-ce-multi", n:["Cross-entropy for flere klasser","Cross-entropy for several classes"],
  f:["$L(\\hat{y}, y) = -\\sum_i y_i \\log(\\hat{y}_i)$", "$L(\\hat{y}, y) = -\\sum_i y_i \\log(\\hat{y}_i)$"],
  e:["Med one-hot-target teller bare den sanne klassen: L = −log ŷ<sub>sann</sub>. Det er kryss-entropien H(p, q) mellom datafordelingen p og modellens q.","With a one-hot target only the true class counts: L = −log ŷ<sub>true</sub>. It is the cross-entropy H(p, q) between the data distribution p and the model's q."],
  ex:["<div class=\"gset\">Bildet viser faktisk en katt, y = (1, 0, 0), men klassifisereren gir ŷ = (0,1, 0,1, 0,8) for katt, hund og fugl.</div><ol class=\"gsteps\"><li>Bare den sanne klassen teller: $L = -1 \\cdot \\ln 0{,}1$</li><li>$L \\approx 2{,}30$</li><li>Hadde den sagt $\\hat{y}_{\\text{katt}} = 0{,}8$: $L = -\\ln 0{,}8 \\approx 0{,}22$</li></ol><div class=\"gans\"><b>Svar:</b> Tapet er 2,30, omtrent 10 ganger høyere enn for et sikkert riktig svar.</div>","<div class=\"gset\">The photo really shows a cat, y = (1, 0, 0), but the classifier outputs ŷ = (0.1, 0.1, 0.8) for cat, dog and bird.</div><ol class=\"gsteps\"><li>Only the true class counts: $L = -1 \\cdot \\ln 0.1$</li><li>$L \\approx 2.30$</li><li>Had it said $\\hat{y}_{\\text{cat}} = 0.8$: $L = -\\ln 0.8 \\approx 0.22$</li></ol><div class=\"gans\"><b>Answer:</b> The loss is 2.30, about 10 times higher than for a confident correct answer.</div>"]},
 {id:"g-params", n:["Antall parametre i et Dense-lag","Number of parameters in a Dense layer"],
  f:["$(n_{\\text{inn}} + 1) \\cdot n_{\\text{ut}}$ &nbsp; (vekter + én bias per node); summer over alle lag", "$(n_{\\text{in}} + 1) \\cdot n_{\\text{out}}$ &nbsp; (weights + one bias per unit); sum over all layers"],
  e:["Hver node har én vekt per input og én bias. Inputlaget har ingen parametre.","Each unit has one weight per input and one bias. The input layer has no parameters."],
  ex:["<div class=\"gset\">En Keras-modell for churn tar 8 input og har Dense-lag med 16, 4 og 1 noder.</div><ol class=\"gsteps\"><li>$(8 + 1) \\cdot 16 = 144$</li><li>$(16 + 1) \\cdot 4 = 68$</li><li>$(4 + 1) \\cdot 1 = 5$</li><li>Totalt: $144 + 68 + 5 = 217$</li></ol><div class=\"gans\"><b>Svar:</b> <code>model.summary()</code> viser 217 trenbare parametre.</div>","<div class=\"gset\">A Keras churn model takes 8 inputs and has Dense layers of 16, 4 and 1 units.</div><ol class=\"gsteps\"><li>$(8 + 1) \\cdot 16 = 144$</li><li>$(16 + 1) \\cdot 4 = 68$</li><li>$(4 + 1) \\cdot 1 = 5$</li><li>Total: $144 + 68 + 5 = 217$</li></ol><div class=\"gans\"><b>Answer:</b> <code>model.summary()</code> reports 217 trainable parameters.</div>"]},
 {id:"g-sgd", n:["Epoker, batcher og iterasjoner","Epochs, batches and iterations"],
  f:["Iterasjoner (vektoppdateringer) per epoke $= \\left\\lceil \\frac{N}{\\text{batch\\_size}} \\right\\rceil$", "Iterations (weight updates) per epoch $= \\left\\lceil \\frac{N}{\\text{batch\\_size}} \\right\\rceil$"],
  e:["En epoke er én gjennomgang av alle treningsdataene. Stochastic/mini-batch gradient descent oppdaterer vektene én gang per batch. Den siste, ufullstendige batchen teller også.","An epoch is one pass over all the training data. Stochastic/mini-batch gradient descent updates the weights once per batch. The last, incomplete batch counts too."],
  ex:["<div class=\"gset\">En bildeklassifiserer trenes på 10 000 bilder med batch size 32 i 10 epoker.</div><ol class=\"gsteps\"><li>$\\frac{10\\,000}{32} = 312{,}5$</li><li>Den siste, mindre batchen teller: $\\lceil 312{,}5 \\rceil = 313$ per epoke</li><li>10 epoker: $10 \\cdot 313 = 3130$ oppdateringer</li></ol><div class=\"gans\"><b>Svar:</b> Vektene oppdateres 313 ganger per epoke og 3130 ganger totalt.</div>","<div class=\"gset\">An image classifier is trained on 10,000 photos with batch size 32 for 10 epochs.</div><ol class=\"gsteps\"><li>$\\frac{10\\,000}{32} = 312.5$</li><li>The last, smaller batch counts: $\\lceil 312.5 \\rceil = 313$ per epoch</li><li>10 epochs: $10 \\cdot 313 = 3130$ updates</li></ol><div class=\"gans\"><b>Answer:</b> The weights are updated 313 times per epoch and 3130 times in total.</div>"]},
 {id:"g-backprop", n:["Kjerneregelen (backpropagation)","The chain rule (backpropagation)"],
  f:["$\\frac{\\partial f}{\\partial x} = \\frac{\\partial f}{\\partial u} \\cdot \\frac{\\partial u}{\\partial x} \\qquad \\frac{\\partial L}{\\partial w} = \\frac{\\partial L}{\\partial a} \\cdot \\frac{\\partial a}{\\partial z} \\cdot \\frac{\\partial z}{\\partial w}$", "$\\frac{\\partial f}{\\partial x} = \\frac{\\partial f}{\\partial u} \\cdot \\frac{\\partial u}{\\partial x} \\qquad \\frac{\\partial L}{\\partial w} = \\frac{\\partial L}{\\partial a} \\cdot \\frac{\\partial a}{\\partial z} \\cdot \\frac{\\partial z}{\\partial w}$"],
  e:["Backpropagation beregner hvordan hver vekt påvirker tapet ved å bruke kjerneregelen bakover gjennom nettverket. Da trengs deriverbare aktiveringer og tap.","Backpropagation computes how each weight affects the loss by applying the chain rule backwards through the network. This needs differentiable activations and loss."],
  ex:["<div class=\"gset\">En spamdetektor med én node har w = 0,5, b = −1, sigmoid og log loss. En e-post med x = 2 er spam (y = 1).</div><ol class=\"gsteps\"><li>Forover: $z = 0{,}5 \\cdot 2 - 1 = 0$, $a = \\sigma(0) = 0{,}5$</li><li>$\\frac{\\partial L}{\\partial a} = -\\frac{1}{a} = -2, \\quad \\frac{\\partial a}{\\partial z} = a(1 - a) = 0{,}25$</li><li>$\\frac{\\partial z}{\\partial w} = x = 2$</li><li>$\\frac{\\partial L}{\\partial w} = -2 \\cdot 0{,}25 \\cdot 2 = -1$</li></ol><div class=\"gans\"><b>Svar:</b> Gradienten er −1, det samme som snarveien (a − y)·x = −0,5·2, så w bør økes.</div>","<div class=\"gset\">A one-unit spam detector has w = 0.5, b = −1, sigmoid and log loss. An email with x = 2 is spam (y = 1).</div><ol class=\"gsteps\"><li>Forward: $z = 0.5 \\cdot 2 - 1 = 0$, $a = \\sigma(0) = 0.5$</li><li>$\\frac{\\partial L}{\\partial a} = -\\frac{1}{a} = -2, \\quad \\frac{\\partial a}{\\partial z} = a(1 - a) = 0.25$</li><li>$\\frac{\\partial z}{\\partial w} = x = 2$</li><li>$\\frac{\\partial L}{\\partial w} = -2 \\cdot 0.25 \\cdot 2 = -1$</li></ol><div class=\"gans\"><b>Answer:</b> The gradient is −1, the same as the shortcut (a − y)·x = −0.5·2, so w should increase.</div>"]}
]},
// ===== 7 Clustering =====
{t:7, items:[
 {id:"g-euclid", n:["Euklidsk avstand","Euclidean distance"],
  f:["$d(p, q) = \\sqrt{(p_1 - q_1)^2 + (p_2 - q_2)^2 + \\dots + (p_n - q_n)^2}$", "$d(p, q) = \\sqrt{(p_1 - q_1)^2 + (p_2 - q_2)^2 + \\dots + (p_n - q_n)^2}$"],
  e:["Grunnlaget for k-means, DBSCAN og k-NN. Features med stort tallområde dominerer, så skaler først. I høye dimensjoner blir avstander mindre informative.","The basis of k-means, DBSCAN and k-NN. Features with a large range dominate, so scale first. In high dimensions distances become less informative."],
  ex:["<div class=\"gset\">Kundesegmentering: kunde A er (alder 30, forbruk 400) og kunde B er (alder 60, forbruk 410).</div><ol class=\"gsteps\"><li>Differanser: $60 - 30 = 30$, $410 - 400 = 10$</li><li>$30^2 + 10^2 = 900 + 100 = 1000$</li><li>$d = \\sqrt{1000} \\approx 31{,}6$</li></ol><div class=\"gans\"><b>Svar:</b> Avstanden er 31,6, mest på grunn av alder; siden forbruk ofte varierer i hundrevis, bør featurene skaleres før klyngeanalyse.</div>","<div class=\"gset\">Customer segmentation: customer A is (age 30, spend 400) and customer B is (age 60, spend 410).</div><ol class=\"gsteps\"><li>Differences: $60 - 30 = 30$, $410 - 400 = 10$</li><li>$30^2 + 10^2 = 900 + 100 = 1000$</li><li>$d = \\sqrt{1000} \\approx 31.6$</li></ol><div class=\"gans\"><b>Answer:</b> The distance is 31.6, driven mostly by age; since spend usually varies in the hundreds, scale the features before clustering.</div>"]},
 {id:"g-kmeans", n:["k-means: tilordning og oppdatering","k-means: assignment and update"],
  f:["Tilordning: $c(x) = \\arg\\min_k d(x, \\mu_k)$<br>Oppdatering: $\\mu_k = \\frac{1}{|C_k|} \\sum_{x \\in C_k} x$", "Assignment: $c(x) = \\arg\\min_k d(x, \\mu_k)$<br>Update: $\\mu_k = \\frac{1}{|C_k|} \\sum_{x \\in C_k} x$"],
  e:["Gjenta de to stegene til sentroidene ikke flytter seg. Resultatet avhenger av startpunktene (lokale minima), og k må velges på forhånd. Klyngene blir konvekse, og alle punkter tilordnes en klynge.","Repeat the two steps until the centroids stop moving. The result depends on the starting points (local minima), and k must be chosen in advance. The clusters are convex, and every point is assigned to a cluster."],
  ex:["<div class=\"gset\">Seks kunder kjøper 1, 2, 4, 8, 9 og 10 varer per måned. k-means med k = 2 starter i μ₁ = 2 og μ₂ = 4.</div><ol class=\"gsteps\"><li>Tilordne: $\\{1, 2\\} \\to \\mu_1$, $\\{4, 8, 9, 10\\} \\to \\mu_2$</li><li>$\\mu_1 = \\frac{1 + 2}{2} = 1{,}5, \\quad \\mu_2 = \\frac{4 + 8 + 9 + 10}{4} = 7{,}75$</li><li>Neste runde: $|4 - 1{,}5| = 2{,}5 < |4 - 7{,}75| = 3{,}75$, så 4 bytter</li><li>$\\mu_1 = \\frac{7}{3} \\approx 2{,}33, \\quad \\mu_2 = 9$</li></ol><div class=\"gans\"><b>Svar:</b> Segmentene ender som {1, 2, 4} (småkjøpere) og {8, 9, 10} (storkjøpere).</div>","<div class=\"gset\">Six customers buy 1, 2, 4, 8, 9 and 10 items per month. k-means with k = 2 starts at μ₁ = 2 and μ₂ = 4.</div><ol class=\"gsteps\"><li>Assign: $\\{1, 2\\} \\to \\mu_1$, $\\{4, 8, 9, 10\\} \\to \\mu_2$</li><li>$\\mu_1 = \\frac{1 + 2}{2} = 1.5, \\quad \\mu_2 = \\frac{4 + 8 + 9 + 10}{4} = 7.75$</li><li>Next round: $|4 - 1.5| = 2.5 < |4 - 7.75| = 3.75$, so 4 switches</li><li>$\\mu_1 = \\frac{7}{3} \\approx 2.33, \\quad \\mu_2 = 9$</li></ol><div class=\"gans\"><b>Answer:</b> The segments settle as {1, 2, 4} (light buyers) and {8, 9, 10} (heavy buyers).</div>"]},
 {id:"g-inertia", n:["Inertia","Inertia"],
  f:["$\\text{Inertia} = \\sum_k \\sum_{x \\in C_k} \\lVert x - \\mu_k \\rVert^2$", "$\\text{Inertia} = \\sum_k \\sum_{x \\in C_k} \\lVert x - \\mu_k \\rVert^2$"],
  e:["Summen av kvadrerte avstander til egen sentroide. Lav er kompakt. Den minker alltid med flere klynger (k = n gir 0), så bruk albuen i inertia-plottet for å velge k.","The sum of squared distances to the cluster's own centroid. Low means compact. It always decreases with more clusters (k = n gives 0), so use the elbow in the inertia plot to choose k."],
  ex:["<div class=\"gset\">Et kundesegment har tre kunder (1, 2), (3, 4) og (5, 9) (besøk, forbruk i hundrelapper).</div><ol class=\"gsteps\"><li>$\\mu = \\left(\\frac{1 + 3 + 5}{3}, \\frac{2 + 4 + 9}{3}\\right) = (3, 5)$</li><li>$\\lVert(-2, -3)\\rVert^2 = 13, \\quad \\lVert(0, -1)\\rVert^2 = 1, \\quad \\lVert(2, 4)\\rVert^2 = 20$</li><li>$\\text{Inertia} = 13 + 1 + 20 = 34$</li></ol><div class=\"gans\"><b>Svar:</b> Segmentet bidrar med 34 til inertia; kunden (5, 9) står alene for 20.</div>","<div class=\"gset\">A customer segment holds three customers (1, 2), (3, 4) and (5, 9) (visits, spend in hundreds).</div><ol class=\"gsteps\"><li>$\\mu = \\left(\\frac{1 + 3 + 5}{3}, \\frac{2 + 4 + 9}{3}\\right) = (3, 5)$</li><li>$\\lVert(-2, -3)\\rVert^2 = 13, \\quad \\lVert(0, -1)\\rVert^2 = 1, \\quad \\lVert(2, 4)\\rVert^2 = 20$</li><li>$\\text{Inertia} = 13 + 1 + 20 = 34$</li></ol><div class=\"gans\"><b>Answer:</b> The segment contributes 34 to the inertia; the customer (5, 9) alone accounts for 20.</div>"]},
 {id:"g-silhouette", n:["Silhouette-koeffisient","Silhouette coefficient"],
  f:["$s = \\frac{b - a}{\\max(a, b)}$", "$s = \\frac{b - a}{\\max(a, b)}$"],
  e:["a er midlere avstand innad i egen klynge, og b midlere avstand til nærmeste andre klynge. s ∈ [−1, 1]: nær 1 er godt plassert, rundt 0 på grensen, og negativ trolig feil klynge. Høyere snitt er bedre, så velg k med toppen.","a is the mean distance within the point's own cluster, and b the mean distance to the nearest other cluster. s ∈ [−1, 1]: close to 1 is well placed, around 0 on the border, and negative probably the wrong cluster. A higher mean is better, so pick the k at the peak."],
  ex:["<div class=\"gset\">Kunde A har snittavstand 2 til eget segment og 5 til nærmeste andre. Kunde B har a = 4, b = 3.</div><ol class=\"gsteps\"><li>A: $s = \\frac{5 - 2}{\\max(2, 5)} = \\frac{3}{5} = 0{,}6$</li><li>B: $s = \\frac{3 - 4}{\\max(4, 3)} = -\\frac{1}{4} = -0{,}25$</li></ol><div class=\"gans\"><b>Svar:</b> A er godt plassert (0,6), mens B er negativ og trolig hører til det andre segmentet.</div>","<div class=\"gset\">Customer A is on average 2 away from its own segment and 5 from the nearest other one. Customer B has a = 4, b = 3.</div><ol class=\"gsteps\"><li>A: $s = \\frac{5 - 2}{\\max(2, 5)} = \\frac{3}{5} = 0.6$</li><li>B: $s = \\frac{3 - 4}{\\max(4, 3)} = -\\frac{1}{4} = -0.25$</li></ol><div class=\"gans\"><b>Answer:</b> A is well placed (0.6), while B is negative and probably belongs to the other segment.</div>"]},
 {id:"g-dbscan", n:["DBSCAN","DBSCAN"],
  f:["$N_\\varepsilon(p) = \\{q : d(p, q) \\le \\varepsilon\\}$ &nbsp; ($p$ selv er med)<br>Kjernepunkt: $|N_\\varepsilon(p)| \\ge \\text{minPts}$ · Kantpunkt: ikke kjerne, men innenfor $\\varepsilon$ av et kjernepunkt · Støy: resten", "$N_\\varepsilon(p) = \\{q : d(p, q) \\le \\varepsilon\\}$ &nbsp; ($p$ itself included)<br>Core point: $|N_\\varepsilon(p)| \\ge \\text{minPts}$ · Border point: not core, but within $\\varepsilon$ of a core point · Noise: the rest"],
  e:["Klynger vokser fra kjernepunkt til kjernepunkt, så formen kan være vilkårlig (måner, ringer). Antall klynger kommer ut av dataene, og støy får label −1. Avhenger sterkt av ε: for liten gir mye støy, for stor slår klynger sammen.","Clusters grow from core point to core point, so they can take any shape (moons, rings). The number of clusters comes out of the data, and noise gets the label −1. It depends strongly on ε: too small gives a lot of noise, too large merges clusters."],
  ex:["<div class=\"gset\">Leveringsstopp ligger langs en vei ved km 1, 2, 2,5, 3, 7, 8 og 15. DBSCAN bruker ε = 1 og minPts = 3.</div><ol class=\"gsteps\"><li>$N(2) = \\{1, 2, 2{,}5, 3\\}, \\ N(2{,}5) = N(3) = \\{2, 2{,}5, 3\\}$</li><li>Så 2, 2,5 og 3 er kjernepunkter ($\\ge 3$)</li><li>$N(1) = \\{1, 2\\}$: ikke kjerne, men innenfor 1 av kjernepunkt 2 $\\Rightarrow$ kant</li><li>$N(7) = N(8) = \\{7, 8\\}$, $N(15) = \\{15\\}$: støy</li></ol><div class=\"gans\"><b>Svar:</b> Én klynge {1, 2, 2,5, 3}; stoppene ved 7, 8 og 15 får label −1.</div>","<div class=\"gset\">Delivery stops lie along a road at km 1, 2, 2.5, 3, 7, 8 and 15. DBSCAN uses ε = 1 and minPts = 3.</div><ol class=\"gsteps\"><li>$N(2) = \\{1, 2, 2.5, 3\\}, \\ N(2.5) = N(3) = \\{2, 2.5, 3\\}$</li><li>So 2, 2.5 and 3 are core points ($\\ge 3$)</li><li>$N(1) = \\{1, 2\\}$: not core, but within 1 of core point 2 $\\Rightarrow$ border</li><li>$N(7) = N(8) = \\{7, 8\\}$, $N(15) = \\{15\\}$: noise</li></ol><div class=\"gans\"><b>Answer:</b> One cluster {1, 2, 2.5, 3}; the stops at 7, 8 and 15 get label −1.</div>"]}
]},
// ===== 8 Dimensionality reduction & anomalies =====
{t:8, items:[
 {id:"g-cov", n:["Kovarians og kovariansmatrise","Covariance and the covariance matrix"],
  f:["$\\text{cov}(x_i, x_j) = \\frac{1}{N - 1} \\sum_{k=1}^{N} (x_{i,k} - \\bar{x}_i)(x_{j,k} - \\bar{x}_j)$<br>$S_{ij} = \\text{cov}(x_i, x_j)$", "$\\text{cov}(x_i, x_j) = \\frac{1}{N - 1} \\sum_{k=1}^{N} (x_{i,k} - \\bar{x}_i)(x_{j,k} - \\bar{x}_j)$<br>$S_{ij} = \\text{cov}(x_i, x_j)$"],
  e:["Diagonalen i S er variansene, og resten er kovariansene. S er symmetrisk. Sentrer dataene (trekk fra snittet) før PCA. Notatene deler på N − 1.","The diagonal of S holds the variances, and the rest are covariances. S is symmetric. Centre the data (subtract the mean) before PCA. The notes divide by N − 1."],
  ex:["<div class=\"gset\">Tre kunder har x₁ = besøk per måned (1, 2, 3) og x₂ = dager siden siste kjøp (2, 1, 0).</div><ol class=\"gsteps\"><li>Snitt: $\\bar{x}_1 = 2, \\ \\bar{x}_2 = 1$; avvik $(-1, 0, 1)$ og $(1, 0, -1)$</li><li>$\\text{cov}(x_1, x_2) = \\frac{-1 + 0 - 1}{3 - 1} = -1$</li><li>$\\text{var}(x_1) = \\text{var}(x_2) = \\frac{1 + 0 + 1}{2} = 1$</li><li>$S = \\begin{pmatrix} 1 & -1 \\\\ -1 & 1 \\end{pmatrix}$</li></ol><div class=\"gans\"><b>Svar:</b> Negativ kovarians: kunder som besøker oftere har handlet nyligere.</div>","<div class=\"gset\">Three customers have x₁ = visits per month (1, 2, 3) and x₂ = days since last purchase (2, 1, 0).</div><ol class=\"gsteps\"><li>Means: $\\bar{x}_1 = 2, \\ \\bar{x}_2 = 1$; deviations $(-1, 0, 1)$ and $(1, 0, -1)$</li><li>$\\text{cov}(x_1, x_2) = \\frac{-1 + 0 - 1}{3 - 1} = -1$</li><li>$\\text{var}(x_1) = \\text{var}(x_2) = \\frac{1 + 0 + 1}{2} = 1$</li><li>$S = \\begin{pmatrix} 1 & -1 \\\\ -1 & 1 \\end{pmatrix}$</li></ol><div class=\"gans\"><b>Answer:</b> Negative covariance: customers who visit more often bought more recently.</div>"]},
 {id:"g-eigen", n:["Egenverdier og egenvektorer","Eigenvalues and eigenvectors"],
  f:["$\\det(S - \\lambda I) = 0$ gir $\\lambda$ &nbsp;·&nbsp; $S\\mathbf{v} = \\lambda \\mathbf{v}$ gir $\\mathbf{v}$ &nbsp;·&nbsp; $\\sum \\lambda = \\text{spor}(S)$", "$\\det(S - \\lambda I) = 0$ gives $\\lambda$ &nbsp;·&nbsp; $S\\mathbf{v} = \\lambda \\mathbf{v}$ gives $\\mathbf{v}$ &nbsp;·&nbsp; $\\sum \\lambda = \\text{trace}(S)$"],
  e:["Hovedkomponentene er egenvektorene til S, sortert etter egenverdi. λ er variansen langs komponenten. Komponentene er ortogonale. Normer egenvektorene til lengde 1.","The principal components are the eigenvectors of S, sorted by eigenvalue. λ is the variance along the component. The components are orthogonal. Normalise the eigenvectors to length 1."],
  ex:["<div class=\"gset\">Etter standardisering av boareal og pris er kovariansmatrisen S = [[2, 1], [1, 2]].</div><ol class=\"gsteps\"><li>$\\det(S - \\lambda I) = (2 - \\lambda)^2 - 1 = 0$</li><li>$2 - \\lambda = \\pm 1 \\;\\Rightarrow\\; \\lambda = 3, \\ 1$</li><li>$\\lambda = 3$: $S\\mathbf{v} = 3\\mathbf{v}$ gir $\\mathbf{v} = \\frac{1}{\\sqrt{2}}(1, 1)$</li><li>Sjekk: $3 + 1 = 4 = \\text{spor}(S)$</li></ol><div class=\"gans\"><b>Svar:</b> PC1 peker langs «stor og dyr» (1, 1)/√2 og bærer varians 3 av totalt 4.</div>","<div class=\"gset\">After standardising house area and price, the covariance matrix is S = [[2, 1], [1, 2]].</div><ol class=\"gsteps\"><li>$\\det(S - \\lambda I) = (2 - \\lambda)^2 - 1 = 0$</li><li>$2 - \\lambda = \\pm 1 \\;\\Rightarrow\\; \\lambda = 3, \\ 1$</li><li>$\\lambda = 3$: $S\\mathbf{v} = 3\\mathbf{v}$ gives $\\mathbf{v} = \\frac{1}{\\sqrt{2}}(1, 1)$</li><li>Check: $3 + 1 = 4 = \\text{trace}(S)$</li></ol><div class=\"gans\"><b>Answer:</b> PC1 points along \"big and expensive\" (1, 1)/√2 and carries variance 3 of the total 4.</div>"]},
 {id:"g-explvar", n:["Forklart varians","Explained variance"],
  f:["Andel for $\\text{PC}_k = \\frac{\\lambda_k}{\\sum_j \\lambda_j}$<br>Kumulativ for de $k$ første $= \\frac{\\lambda_1 + \\dots + \\lambda_k}{\\sum_j \\lambda_j}$", "Share for $\\text{PC}_k = \\frac{\\lambda_k}{\\sum_j \\lambda_j}$<br>Cumulative for the first $k$ $= \\frac{\\lambda_1 + \\dots + \\lambda_k}{\\sum_j \\lambda_j}$"],
  e:["Velg det minste antallet komponenter som når ønsket andel (f.eks. 90 %), eller se etter knekken i scree-plottet. Del egenverdiene på summen før du leser av andeler. Mest varians er ikke alltid mest nyttig for klassifisering.","Choose the smallest number of components that reaches the desired share (e.g. 90 %), or look for the bend in the scree plot. Divide the eigenvalues by their sum before reading off shares. Most variance is not always most useful for classification."],
  ex:["<div class=\"gset\">PCA på en kundeundersøkelse med 5 features gir egenverdier λ = 4, 2, 1, 0,5, 0,5. Mål: minst 90 % varians.</div><ol class=\"gsteps\"><li>$\\sum \\lambda = 4 + 2 + 1 + 0{,}5 + 0{,}5 = 8$</li><li>$\\frac{4}{8} = 50\\,\\%, \\quad \\frac{4 + 2}{8} = 75\\,\\%$</li><li>$\\frac{7}{8} = 87{,}5\\,\\%, \\quad \\frac{7{,}5}{8} \\approx 93{,}8\\,\\%$</li></ol><div class=\"gans\"><b>Svar:</b> To komponenter forklarer 75 %, men det trengs 4 for å nå over 90 %.</div>","<div class=\"gset\">PCA on a customer survey with 5 features gives eigenvalues λ = 4, 2, 1, 0.5, 0.5. Goal: at least 90 % variance.</div><ol class=\"gsteps\"><li>$\\sum \\lambda = 4 + 2 + 1 + 0.5 + 0.5 = 8$</li><li>$\\frac{4}{8} = 50\\,\\%, \\quad \\frac{4 + 2}{8} = 75\\,\\%$</li><li>$\\frac{7}{8} = 87.5\\,\\%, \\quad \\frac{7.5}{8} \\approx 93.8\\,\\%$</li></ol><div class=\"gans\"><b>Answer:</b> Two components explain 75 %, but 4 are needed to pass 90 %.</div>"]},
 {id:"g-project", n:["Projeksjon og rekonstruksjon","Projection and reconstruction"],
  f:["$z_k = \\mathbf{e}_k^\\top (\\mathbf{x} - \\bar{\\mathbf{x}}) \\qquad \\hat{\\mathbf{x}} = \\bar{\\mathbf{x}} + \\sum_k z_k\\, \\mathbf{e}_k$<br>Rekonstruksjonsfeil $= \\lVert \\mathbf{x} - \\hat{\\mathbf{x}} \\rVert^2$", "$z_k = \\mathbf{e}_k^\\top (\\mathbf{x} - \\bar{\\mathbf{x}}) \\qquad \\hat{\\mathbf{x}} = \\bar{\\mathbf{x}} + \\sum_k z_k\\, \\mathbf{e}_k$<br>Reconstruction error $= \\lVert \\mathbf{x} - \\hat{\\mathbf{x}} \\rVert^2$"],
  e:["z er de nye koordinatene (features) etter PCA. Med færre komponenter enn features mister du informasjon. Høy rekonstruksjonsfeil (PCA eller autoencoder) tyder på et uvanlig punkt, og kan brukes til anomalideteksjon.","z are the new coordinates (features) after PCA. With fewer components than features you lose information. A high reconstruction error (PCA or autoencoder) suggests an unusual point, and can be used for anomaly detection."],
  ex:["<div class=\"gset\">En kunde ligger i x − x̄ = (3, 1) etter sentrering. PCA beholder bare PC1, e₁ = (1, 1)/√2.</div><ol class=\"gsteps\"><li>$z_1 = \\frac{3 + 1}{\\sqrt{2}} = \\frac{4}{\\sqrt{2}} \\approx 2{,}83$</li><li>$\\hat{\\mathbf{x}} - \\bar{\\mathbf{x}} = 2{,}83 \\cdot \\frac{1}{\\sqrt{2}}(1, 1) = (2, 2)$</li><li>$\\mathbf{x} - \\hat{\\mathbf{x}} = (3, 1) - (2, 2) = (1, -1)$</li><li>$\\lVert(1, -1)\\rVert^2 = 1 + 1 = 2$</li></ol><div class=\"gans\"><b>Svar:</b> Kundens nye feature er 2,83 og rekonstruksjonsfeilen er 2; mye større feil ville flagget en uvanlig kunde.</div>","<div class=\"gset\">A customer lies at x − x̄ = (3, 1) after centring. PCA keeps only PC1, e₁ = (1, 1)/√2.</div><ol class=\"gsteps\"><li>$z_1 = \\frac{3 + 1}{\\sqrt{2}} = \\frac{4}{\\sqrt{2}} \\approx 2.83$</li><li>$\\hat{\\mathbf{x}} - \\bar{\\mathbf{x}} = 2.83 \\cdot \\frac{1}{\\sqrt{2}}(1, 1) = (2, 2)$</li><li>$\\mathbf{x} - \\hat{\\mathbf{x}} = (3, 1) - (2, 2) = (1, -1)$</li><li>$\\lVert(1, -1)\\rVert^2 = 1 + 1 = 2$</li></ol><div class=\"gans\"><b>Answer:</b> The customer's new feature is 2.83 and the reconstruction error is 2; much larger errors would flag an unusual customer.</div>"]},
 {id:"g-tsne", n:["t-SNE (ingen formel å regne)","t-SNE (no formula to compute)"],
  f:["Bevarer <i>lokale</i> naboskap · ingen gjenbrukbar projeksjon · <code>fit_transform</code> på nytt for nye data","Preserves <i>local</i> neighbourhoods · no reusable projection · <code>fit_transform</code> again for new data"],
  e:["t-SNE optimerer plasseringen av punktene direkte i 2D/3D i stedet for å lære en transformasjon. Avstander mellom klynger og klyngestørrelser i plottet betyr lite. Bruk det til visualisering, ikke som features.","t-SNE optimises the positions of the points directly in 2D/3D instead of learning a transform. Distances between clusters and cluster sizes in the plot mean little. Use it for visualisation, not as features."]},
 {id:"g-anomaly", n:["Anomalideteksjon","Anomaly detection"],
  f:["Isolation Forest: antall flagget $\\approx \\text{contamination} \\cdot n$; kort snittlig stilengde = anomali<br>k-means: skår $= \\min_k \\lVert x - \\mu_k \\rVert$ over en terskel · DBSCAN: støypunkter ($-1$)", "Isolation Forest: number flagged $\\approx \\text{contamination} \\cdot n$; short mean path length = anomaly<br>k-means: score $= \\min_k \\lVert x - \\mu_k \\rVert$ above a threshold · DBSCAN: noise points ($-1$)"],
  e:["Anomalier er få og annerledes, så de isoleres med få tilfeldige splitter. contamination er din antakelse om andelen anomalier og bestemmer terskelen.","Anomalies are few and different, so they are isolated with few random splits. contamination is your assumption about the share of anomalies and sets the threshold."],
  ex:["<div class=\"gset\">En bank kjører Isolation Forest på 1500 korttransaksjoner med <code>contamination=0.02</code>, og sjekker også k-means-avstander med terskel 3.</div><ol class=\"gsteps\"><li>Flagget: $0{,}02 \\cdot 1500 = 30$ transaksjoner</li><li>En transaksjon er $6$ og $4{,}5$ fra de to sentroidene: skår $= \\min(6, 4{,}5) = 4{,}5$</li><li>$4{,}5 > 3 \\;\\Rightarrow$ anomali</li></ol><div class=\"gans\"><b>Svar:</b> Omtrent 30 transaksjoner sendes til manuell kontroll, og k-means-sjekken flagger også denne.</div>","<div class=\"gset\">A bank runs Isolation Forest on 1500 card transactions with <code>contamination=0.02</code>, and also checks k-means distances with threshold 3.</div><ol class=\"gsteps\"><li>Flagged: $0.02 \\cdot 1500 = 30$ transactions</li><li>A transaction is $6$ and $4.5$ from the two centroids: score $= \\min(6, 4.5) = 4.5$</li><li>$4.5 > 3 \\;\\Rightarrow$ anomaly</li></ol><div class=\"gans\"><b>Answer:</b> About 30 transactions go to manual review, and the k-means check also flags this one.</div>"]}
]},
// ===== 9 Reinforcement learning =====
{t:9, items:[
 {id:"g-return", n:["Diskontert retur","Discounted return"],
  f:["$G_t = R_{t+1} + \\gamma R_{t+2} + \\gamma^2 R_{t+3} + \\dots = \\sum_{k \\ge 0} \\gamma^k R_{t+k+1}$<br>$\\sum_{k \\ge 0} \\gamma^k = \\frac{1}{1 - \\gamma}$", "$G_t = R_{t+1} + \\gamma R_{t+2} + \\gamma^2 R_{t+3} + \\dots = \\sum_{k \\ge 0} \\gamma^k R_{t+k+1}$<br>$\\sum_{k \\ge 0} \\gamma^k = \\frac{1}{1 - \\gamma}$"],
  e:["En belønning k steg frem vektes med γ<sup>k</sup>, og den første (R<sub>t+1</sub>) har vekt 1. Liten γ gir en kortsiktig agent, stor γ en langsiktig. Med γ < 1 blir en uendelig sum endelig.","A reward k steps ahead is weighted by γ<sup>k</sup>, and the first one (R<sub>t+1</sub>) has weight 1. A small γ gives a short-sighted agent, a large γ a far-sighted one. With γ < 1 an infinite sum becomes finite."],
  ex:["<div class=\"gset\">En Frozen Lake-robot får belønningene 1, 0, 2 på de neste tre stegene, med γ = 0,9.</div><ol class=\"gsteps\"><li>$G = 1 + 0{,}9 \\cdot 0 + 0{,}9^2 \\cdot 2$</li><li>$0{,}9^2 \\cdot 2 = 0{,}81 \\cdot 2 = 1{,}62$</li><li>$G = 1 + 0 + 1{,}62 = 2{,}62$</li><li>Belønning 2 for alltid, $\\gamma = 0{,}95$: $G = \\frac{2}{1 - 0{,}95} = 40$</li></ol><div class=\"gans\"><b>Svar:</b> Returen er 2,62; den senere belønningen på 2 er bare verdt 1,62 nå.</div>","<div class=\"gset\">A Frozen Lake robot receives rewards 1, 0, 2 on its next three steps, with γ = 0.9.</div><ol class=\"gsteps\"><li>$G = 1 + 0.9 \\cdot 0 + 0.9^2 \\cdot 2$</li><li>$0.9^2 \\cdot 2 = 0.81 \\cdot 2 = 1.62$</li><li>$G = 1 + 0 + 1.62 = 2.62$</li><li>Reward 2 forever, $\\gamma = 0.95$: $G = \\frac{2}{1 - 0.95} = 40$</li></ol><div class=\"gans\"><b>Answer:</b> The return is 2.62; the later reward of 2 is only worth 1.62 today.</div>"]},
 {id:"g-qlearning", n:["Q-learning (Bellman-oppdatering)","Q-learning (Bellman update)"],
  f:["$Q_{\\text{new}}(S_t, A_t) \\leftarrow (1 - \\alpha)\\, Q(S_t, A_t) + \\alpha \\left(R_{t+1} + \\gamma \\max_A Q(S_{t+1}, A)\\right)$", "$Q_{\\text{new}}(S_t, A_t) \\leftarrow (1 - \\alpha)\\, Q(S_t, A_t) + \\alpha \\left(R_{t+1} + \\gamma \\max_A Q(S_{t+1}, A)\\right)$"],
  e:["α er læringsraten: α = 0 lærer ingenting og α = 1 glemmer den gamle verdien. γ er diskonteringsfaktoren. Målet R + γ·max Q bruker den beste handlingen i neste tilstand.","α is the learning rate: α = 0 learns nothing and α = 1 forgets the old value. γ is the discount factor. The target R + γ·max Q uses the best action in the next state."],
  ex:["<div class=\"gset\">En Frozen Lake-robot har Q(s, høyre) = 1. Den går til høyre, får R = −1 og lander der beste Q er 6. α = 0,1, γ = 0,95.</div><ol class=\"gsteps\"><li>Mål: $R + \\gamma \\max Q' = -1 + 0{,}95 \\cdot 6 = 4{,}7$</li><li>$(1 - \\alpha)\\, Q = 0{,}9 \\cdot 1 = 0{,}9$</li><li>$Q_{\\text{new}} = 0{,}9 + 0{,}1 \\cdot 4{,}7 = 1{,}37$</li></ol><div class=\"gans\"><b>Svar:</b> Q øker fra 1 til 1,37, altså 10 % av veien mot målet 4,7.</div>","<div class=\"gset\">A Frozen Lake robot has Q(s, right) = 1. It moves right, gets R = −1 and lands where the best Q is 6. α = 0.1, γ = 0.95.</div><ol class=\"gsteps\"><li>Target: $R + \\gamma \\max Q' = -1 + 0.95 \\cdot 6 = 4.7$</li><li>$(1 - \\alpha)\\, Q = 0.9 \\cdot 1 = 0.9$</li><li>$Q_{\\text{new}} = 0.9 + 0.1 \\cdot 4.7 = 1.37$</li></ol><div class=\"gans\"><b>Answer:</b> Q rises from 1 to 1.37, moving 10 % of the way towards the target 4.7.</div>"]},
 {id:"g-vq", n:["Verdi og Q-verdi (deterministisk)","Value and Q-value (deterministic)"],
  f:["$V(s) = \\max_a Q(s, a) \\qquad Q(s, a) = R(s, a) + \\gamma\\, V(s') \\qquad \\pi(s) = \\arg\\max_a Q(s, a)$", "$V(s) = \\max_a Q(s, a) \\qquad Q(s, a) = R(s, a) + \\gamma\\, V(s') \\qquad \\pi(s) = \\arg\\max_a Q(s, a)$"],
  e:["s′ er tilstanden handlingen a fører til. En terminal tilstand (hull eller mål) har ingen fremtid, så Q = bare belønningen. Den grådige policyen velger handlingen med størst Q.","s′ is the state that action a leads to. A terminal state (hole or goal) has no future, so Q = just the reward. The greedy policy picks the action with the largest Q."],
  ex:["<div class=\"gset\">En Frozen Lake-robot er 6 steg fra 🎁 (belønning 1, alle andre belønninger 0), γ = 0,9.</div><ol class=\"gsteps\"><li>Siste steg inn i terminal 🎁: $Q = 1 + 0 = 1$, så $V = 1$</li><li>Ett steg lenger bak: $V = 0 + 0{,}9 \\cdot 1 = 0{,}9$</li><li>Hvert ekstra steg ganger med 0,9: $V(\\text{start}) = 0{,}9^5 \\approx 0{,}59$</li><li>Handling inn i et hull: $Q = 0$</li></ol><div class=\"gans\"><b>Svar:</b> V(start) ≈ 0,59, og den grådige policyen følger korteste trygge vei.</div>","<div class=\"gset\">A Frozen Lake robot is 6 steps from the 🎁 (reward 1, all other rewards 0), γ = 0.9.</div><ol class=\"gsteps\"><li>Last step into the terminal 🎁: $Q = 1 + 0 = 1$, so $V = 1$</li><li>One step further back: $V = 0 + 0.9 \\cdot 1 = 0.9$</li><li>Each extra step multiplies by 0.9: $V(\\text{start}) = 0.9^5 \\approx 0.59$</li><li>Action into a hole: $Q = 0$</li></ol><div class=\"gans\"><b>Answer:</b> V(start) ≈ 0.59, and the greedy policy follows the shortest safe path.</div>"]},
 {id:"g-egreedy", n:["ε-greedy","ε-greedy"],
  f:["$P(\\text{grådig}) = (1 - \\varepsilon) + \\frac{\\varepsilon}{|A|} \\qquad P(\\text{annen handling}) = \\frac{\\varepsilon}{|A|}$<br>(tilfeldig valg blant alle $|A|$)", "$P(\\text{greedy}) = (1 - \\varepsilon) + \\frac{\\varepsilon}{|A|} \\qquad P(\\text{other action}) = \\frac{\\varepsilon}{|A|}$<br>(random pick among all $|A|$)"],
  e:["Med sannsynlighet ε utforsker agenten (tilfeldig handling), ellers utnytter den (argmax Q). Det tilfeldige valget kan også treffe den grådige handlingen.","With probability ε the agent explores (random action), otherwise it exploits (argmax Q). The random pick can also land on the greedy action."],
  ex:["<div class=\"gset\">En Frozen Lake-robot har 4 handlinger (venstre, ned, høyre, opp) og utforsker med ε = 0,2.</div><ol class=\"gsteps\"><li>Tilfeldig valg av én bestemt handling: $\\frac{0{,}2}{4} = 0{,}05$</li><li>$P(\\text{grådig}) = 0{,}8 + 0{,}05 = 0{,}85$</li><li>Sjekk: $0{,}85 + 3 \\cdot 0{,}05 = 1$</li></ol><div class=\"gans\"><b>Svar:</b> Roboten tar den beste kjente handlingen 85 % av gangene og hver av de andre 5 %.</div>","<div class=\"gset\">A Frozen Lake robot has 4 actions (left, down, right, up) and explores with ε = 0.2.</div><ol class=\"gsteps\"><li>Random pick of one specific action: $\\frac{0.2}{4} = 0.05$</li><li>$P(\\text{greedy}) = 0.8 + 0.05 = 0.85$</li><li>Check: $0.85 + 3 \\cdot 0.05 = 1$</li></ol><div class=\"gans\"><b>Answer:</b> The robot takes the best-known action 85 % of the time and each other action 5 %.</div>"]},
 {id:"g-edecay", n:["Epsilon decay","Epsilon decay"],
  f:["$\\varepsilon \\leftarrow \\max(\\varepsilon_{\\min},\\ \\varepsilon \\cdot \\text{decay})$ $\\;\\Rightarrow\\;$ $\\varepsilon_n = \\max(\\varepsilon_{\\min},\\ \\varepsilon_0 \\cdot \\text{decay}^n)$<br>$n = \\frac{\\ln(\\varepsilon_{\\min} / \\varepsilon_0)}{\\ln(\\text{decay})}$", "$\\varepsilon \\leftarrow \\max(\\varepsilon_{\\min},\\ \\varepsilon \\cdot \\text{decay})$ $\\;\\Rightarrow\\;$ $\\varepsilon_n = \\max(\\varepsilon_{\\min},\\ \\varepsilon_0 \\cdot \\text{decay}^n)$<br>$n = \\frac{\\ln(\\varepsilon_{\\min} / \\varepsilon_0)}{\\ln(\\text{decay})}$"],
  e:["Høy ε tidlig (mye utforsking) og lav ε senere (utnytt det som er lært). Geometrisk decay er ikke det samme som å trekke fra en fast verdi.","A high ε early (much exploration) and a low ε later (exploit what has been learned). Geometric decay is not the same as subtracting a fixed amount."],
  ex:["<div class=\"gset\">En Frozen Lake-agent starter med ε₀ = 1 og ganger ε med 0,99 etter hver episode, ned til ε_min = 0,05.</div><ol class=\"gsteps\"><li>$\\varepsilon_{100} = 0{,}99^{100} \\approx 0{,}37$</li><li>$n = \\frac{\\ln 0{,}05}{\\ln 0{,}99} = \\frac{-3{,}00}{-0{,}01005} \\approx 298$</li><li>Deretter: $\\varepsilon = 0{,}05$ ligger fast</li></ol><div class=\"gans\"><b>Svar:</b> Etter 100 episoder utforsker agenten fortsatt 37 % av gangene; fra episode ≈ 298 bare 5 %.</div>","<div class=\"gset\">A Frozen Lake agent starts with ε₀ = 1 and multiplies ε by 0.99 after each episode, down to ε_min = 0.05.</div><ol class=\"gsteps\"><li>$\\varepsilon_{100} = 0.99^{100} \\approx 0.37$</li><li>$n = \\frac{\\ln 0.05}{\\ln 0.99} = \\frac{-3.00}{-0.01005} \\approx 298$</li><li>After that: $\\varepsilon = 0.05$ stays fixed</li></ol><div class=\"gans\"><b>Answer:</b> After 100 episodes the agent still explores 37 % of the time; from episode ≈ 298 it explores only 5 %.</div>"]},
 {id:"g-dqn", n:["Deep Q-learning (DQN)","Deep Q-learning (DQN)"],
  f:["$y = R + \\gamma \\max_{a'} Q_{\\text{target}}(S', a')$ &nbsp; ($y = R$ hvis terminal)<br>$\\text{Loss} = \\left(y - Q(S, A)\\right)^2$", "$y = R + \\gamma \\max_{a'} Q_{\\text{target}}(S', a')$ &nbsp; ($y = R$ if terminal)<br>$\\text{Loss} = \\left(y - Q(S, A)\\right)^2$"],
  e:["Et nevralt nett erstatter Q-tabellen. Target network (oppdateres sjeldnere) gir et stabilt mål, og en replay buffer gir mindre korrelerte treningsdata. Lossen er MSE, og den backpropageres gjennom Q-nettet.","A neural network replaces the Q table. The target network (updated less often) gives a stable target, and a replay buffer gives less correlated training data. The loss is MSE, and it is backpropagated through the Q network."],
  ex:["<div class=\"gset\">En DQN-robot på Frozen Lake tar et steg med R = 0. Target-nettet gir max Q = 0,5 i neste tilstand, Q-nettet gir Q(S, A) = 0,3, og γ = 0,9.</div><ol class=\"gsteps\"><li>$y = 0 + 0{,}9 \\cdot 0{,}5 = 0{,}45$</li><li>$\\text{Loss} = (0{,}45 - 0{,}3)^2 = 0{,}15^2 = 0{,}0225$</li><li>Hvis $S'$ var et hull (terminal): $y = 0$, loss $= 0{,}3^2 = 0{,}09$</li></ol><div class=\"gans\"><b>Svar:</b> Lossen 0,0225 backpropageres for å dytte Q(S, A) opp mot 0,45.</div>","<div class=\"gset\">A DQN robot on Frozen Lake takes a step with R = 0. The target network gives max Q = 0.5 in the next state, the Q network gives Q(S, A) = 0.3, and γ = 0.9.</div><ol class=\"gsteps\"><li>$y = 0 + 0.9 \\cdot 0.5 = 0.45$</li><li>$\\text{Loss} = (0.45 - 0.3)^2 = 0.15^2 = 0.0225$</li><li>If $S'$ were a hole (terminal): $y = 0$, loss $= 0.3^2 = 0.09$</li></ol><div class=\"gans\"><b>Answer:</b> The loss 0.0225 is backpropagated to push Q(S, A) up towards 0.45.</div>"]}
]},
// ===== 10 XAI =====
{t:10, items:[
 {id:"g-shapley", n:["Shapley-verdi","Shapley value"],
  f:["$\\varphi_i = \\sum_{S \\subseteq N \\setminus \\{i\\}} \\frac{|S|!\\,(n - |S| - 1)!}{n!} \\left[v(S \\cup \\{i\\}) - v(S)\\right]$", "$\\varphi_i = \\sum_{S \\subseteq N \\setminus \\{i\\}} \\frac{|S|!\\,(n - |S| - 1)!}{n!} \\left[v(S \\cup \\{i\\}) - v(S)\\right]$"],
  e:["Snittet av spiller i sitt marginale bidrag over alle rekkefølger spillerne kan ankomme i. v er den karakteristiske funksjonen (verdien av en koalisjon). Egenskaper: efficiency, symmetry, dummy og additivity.","The mean of player i's marginal contribution over all orders in which the players can arrive. v is the characteristic function (the value of a coalition). Properties: efficiency, symmetry, dummy and additivity."],
  ex:["<div class=\"gset\">En lånemodell har to features, inntekt (A) og gjeld (B). Skåren over basis er v(∅) = 0, v(A) = 10, v(B) = 20, v(AB) = 40.</div><ol class=\"gsteps\"><li>A først: $v(A) - v(\\emptyset) = 10$; A sist: $v(AB) - v(B) = 20$</li><li>$\\varphi_A = \\frac{1}{2} \\cdot 10 + \\frac{1}{2} \\cdot 20 = 15$</li><li>$\\varphi_B = \\frac{1}{2} \\cdot 20 + \\frac{1}{2} \\cdot 30 = 25$</li><li>Efficiency: $15 + 25 = 40 = v(AB)$</li></ol><div class=\"gans\"><b>Svar:</b> Inntekt får 15 og gjeld 25 av de 40 poengene.</div>","<div class=\"gset\">A loan model has two features, income (A) and debt (B). The score above baseline is v(∅) = 0, v(A) = 10, v(B) = 20, v(AB) = 40.</div><ol class=\"gsteps\"><li>A first: $v(A) - v(\\emptyset) = 10$; A second: $v(AB) - v(B) = 20$</li><li>$\\varphi_A = \\frac{1}{2} \\cdot 10 + \\frac{1}{2} \\cdot 20 = 15$</li><li>$\\varphi_B = \\frac{1}{2} \\cdot 20 + \\frac{1}{2} \\cdot 30 = 25$</li><li>Efficiency: $15 + 25 = 40 = v(AB)$</li></ol><div class=\"gans\"><b>Answer:</b> Income gets 15 and debt 25 of the 40 points.</div>"]},
 {id:"g-shap-eff", n:["SHAP: lokal nøyaktighet","SHAP: local accuracy"],
  f:["$f(x) = \\varphi_0 + \\sum_i \\varphi_i, \\qquad \\varphi_0 = E[f(x)]$", "$f(x) = \\varphi_0 + \\sum_i \\varphi_i, \\qquad \\varphi_0 = E[f(x)]$"],
  e:["SHAP-verdiene for én prediksjon summerer til avviket fra basisverdien (snittprediksjonen). Det er dette waterfall-plottet viser. Global viktighet er snittet av |φ<sub>i</sub>| over mange punkter.","The SHAP values for one prediction sum to the difference from the base value (the mean prediction). This is what the waterfall plot shows. Global importance is the mean of |φ<sub>i</sub>| over many points."],
  ex:["<div class=\"gset\">En Titanic-modell har basisverdi φ₀ = 0,30. For én passasjer er f(x) = 0,72, φ_Age = 0,10 og φ_Fare = −0,05.</div><ol class=\"gsteps\"><li>Totalt å forklare: $0{,}72 - 0{,}30 = 0{,}42$</li><li>$\\varphi_{\\text{Sex}} = 0{,}42 - 0{,}10 - (-0{,}05) = 0{,}37$</li><li>Sjekk: $0{,}30 + 0{,}10 - 0{,}05 + 0{,}37 = 0{,}72$</li></ol><div class=\"gans\"><b>Svar:</b> Kjønn løfter overlevelsessannsynligheten med 0,37, det største bidraget i waterfall-plottet.</div>","<div class=\"gset\">A Titanic survival model has base value φ₀ = 0.30. For one passenger f(x) = 0.72, φ_Age = 0.10 and φ_Fare = −0.05.</div><ol class=\"gsteps\"><li>Total to explain: $0.72 - 0.30 = 0.42$</li><li>$\\varphi_{\\text{Sex}} = 0.42 - 0.10 - (-0.05) = 0.37$</li><li>Check: $0.30 + 0.10 - 0.05 + 0.37 = 0.72$</li></ol><div class=\"gans\"><b>Answer:</b> Sex pushes this passenger's survival probability up by 0.37, the largest contribution in the waterfall plot.</div>"]},
 {id:"g-coalitions", n:["Antall koalisjoner","Number of coalitions"],
  f:["Antall delmengder av $n$ spillere $= 2^n$", "Number of subsets of $n$ players $= 2^n$"],
  e:["En eksakt Shapley-beregning må i prinsippet evaluere v for alle koalisjoner. Derfor bruker SHAP tilnærminger (sampling, KernelSHAP, TreeSHAP). I Image SHAP er superpikslene spillerne.","An exact Shapley computation must in principle evaluate v for every coalition. That is why SHAP uses approximations (sampling, KernelSHAP, TreeSHAP). In Image SHAP the superpixels are the players."],
  ex:["<div class=\"gset\">Image SHAP forklarer en hundeklassifiserer ved å dele bildet i superpiksler.</div><ol class=\"gsteps\"><li>10 superpiksler: $2^{10} = 1024$ koalisjoner</li><li>20 superpiksler: $2^{20} = 1\\,048\\,576$ koalisjoner</li><li>Hver ekstra superpiksel dobler antallet</li></ol><div class=\"gans\"><b>Svar:</b> Over en million modellkall for 20 superpiksler, og derfor sampler SHAP koalisjoner i stedet.</div>","<div class=\"gset\">Image SHAP explains a dog classifier by splitting the photo into superpixels.</div><ol class=\"gsteps\"><li>10 superpixels: $2^{10} = 1024$ coalitions</li><li>20 superpixels: $2^{20} = 1{,}048{,}576$ coalitions</li><li>Each added superpixel doubles the count</li></ol><div class=\"gans\"><b>Answer:</b> Over a million model calls for 20 superpixels, which is why SHAP samples coalitions instead.</div>"]},
 {id:"g-tcav", n:["TCAV-skår","TCAV score"],
  f:["$\\text{TCAV}_{C,k,l} = \\frac{|\\{x \\in X_k : S_{C,k,l}(x) > 0\\}|}{|X_k|}$", "$\\text{TCAV}_{C,k,l} = \\frac{|\\{x \\in X_k : S_{C,k,l}(x) > 0\\}|}{|X_k|}$"],
  e:["Andelen bilder av klasse k der en bevegelse i retning av konseptet C (konseptvektoren, CAV) i lag l øker skåren for k. Et globalt, modellspesifikt mål på hvor viktig et menneskelig konsept er.","The share of images of class k where moving in the direction of concept C (the concept vector, CAV) in layer l increases the score for k. A global, model-specific measure of how important a human concept is."],
  ex:["<div class=\"gset\">Vi tester om konseptet «striper» betyr noe for en sebraklassifiserer: av 160 sebrabilder får 112 høyere sebraskår når de flyttes langs stripe-CAV-en.</div><ol class=\"gsteps\"><li>$|\\{x : S(x) > 0\\}| = 112, \\quad |X_k| = 160$</li><li>$\\text{TCAV} = \\frac{112}{160} = 0{,}70$</li><li>Sammenlign med tilfeldige konsepter (rundt $0{,}5$)</li></ol><div class=\"gans\"><b>Svar:</b> Striper dytter 70 % av sebrabildene mot «sebra», så modellen bruker konseptet.</div>","<div class=\"gset\">We test whether the concept \"stripes\" matters for a zebra classifier: of 160 zebra images, 112 get a higher zebra score when moved along the stripes CAV.</div><ol class=\"gsteps\"><li>$|\\{x : S(x) > 0\\}| = 112, \\quad |X_k| = 160$</li><li>$\\text{TCAV} = \\frac{112}{160} = 0.70$</li><li>Compare with random concepts (about $0.5$)</li></ol><div class=\"gans\"><b>Answer:</b> 70 % of zebra images are pushed towards \"zebra\" by stripes, so the model relies on the concept.</div>"]}
]},
// ===== 11 AI Act =====
{t:11, items:[
 {id:"g-fines", n:["Bøter (Artikkel 99)","Fines (Article 99)"],
  f:["Forbudt praksis (Art. 5): inntil $\\max\\left(\\text{35 mill. EUR},\\ 7\\,\\% \\times \\text{global årsomsetning}\\right)$<br>De fleste andre brudd: inntil $\\max\\left(\\text{15 mill. EUR},\\ 3\\,\\% \\times \\text{omsetning}\\right)$", "Prohibited practices (Art. 5): up to $\\max\\left(\\text{EUR 35M},\\ 7\\,\\% \\times \\text{global annual turnover}\\right)$<br>Most other breaches: up to $\\max\\left(\\text{EUR 15M},\\ 3\\,\\% \\times \\text{turnover}\\right)$"],
  e:["Det <b>høyeste</b> av det faste beløpet og prosentandelen gjelder. Regn ut begge og velg det største.","The <b>higher</b> of the fixed amount and the percentage applies. Compute both and take the larger."],
  ex:["<div class=\"gset\">Selskap A (global omsetning €2 mrd.) driver forbudt sosial poengsetting. Selskap B (€300 mill.) bryter høyrisikopliktene i et rekrutteringsverktøy.</div><ol class=\"gsteps\"><li>A: $7\\,\\% \\cdot 2000 = 140$ mill. € $> 35$ mill. €</li><li>A: maksimal bot €140 mill.</li><li>B: $3\\,\\% \\cdot 300 = 9$ mill. € $< 15$ mill. €</li><li>B: maksimal bot €15 mill.</li></ol><div class=\"gans\"><b>Svar:</b> A risikerer inntil €140 mill. (prosenten vinner), B inntil €15 mill. (fastbeløpet vinner).</div>","<div class=\"gset\">Company A (global turnover €2 bn) runs a banned social-scoring system. Company B (€300 M) breaches high-risk duties in a hiring tool.</div><ol class=\"gsteps\"><li>A: $7\\,\\% \\cdot 2000 = 140$ M€ $> 35$ M€</li><li>A: maximum fine €140 M</li><li>B: $3\\,\\% \\cdot 300 = 9$ M€ $< 15$ M€</li><li>B: maximum fine €15 M</li></ol><div class=\"gans\"><b>Answer:</b> A risks up to €140 M (the percentage wins), B up to €15 M (the fixed amount wins).</div>"]},
 {id:"g-gpai", n:["GPAI og systemisk risiko (Artikkel 51)","GPAI and systemic risk (Article 51)"],
  f:["Treningsberegning: $C \\approx 6 \\cdot N \\cdot D$ FLOP &nbsp; ($N$ = parametre, $D$ = treningstokens)<br>$C > 10^{25}$ FLOP $\\Rightarrow$ antatt systemisk risiko", "Training compute: $C \\approx 6 \\cdot N \\cdot D$ FLOP &nbsp; ($N$ = parameters, $D$ = training tokens)<br>$C > 10^{25}$ FLOP $\\Rightarrow$ presumed systemic risk"],
  e:["Over terskelen antas en GPAI-modell å ha systemisk risiko, med ekstra plikter. Kommisjonen kan også utpeke modeller under terskelen (Anneks 13). Høy beregning gjør ikke en modell til et høyrisikosystem; det er en annen kategori.","Above the threshold a GPAI model is presumed to have systemic risk, with extra obligations. The Commission can also designate models below the threshold (Annex 13). High compute does not make a model a high-risk system; that is a different category."],
  ex:["<div class=\"gset\">En språkmodell har N = 7·10¹⁰ parametre og trenes på D = 1,5·10¹³ tokens.</div><ol class=\"gsteps\"><li>$6 \\cdot 7 \\cdot 1{,}5 = 63$</li><li>$C \\approx 63 \\cdot 10^{10 + 13} = 6{,}3 \\cdot 10^{24}$ FLOP</li><li>$6{,}3 \\cdot 10^{24} < 10^{25}$</li><li>Dobbelt så mange tokens: $1{,}26 \\cdot 10^{25} > 10^{25}$</li></ol><div class=\"gans\"><b>Svar:</b> Modellen antas ikke å ha systemisk risiko, men dobbelt så mye treningsdata ville krysset terskelen.</div>","<div class=\"gset\">A language model has N = 7·10¹⁰ parameters and is trained on D = 1.5·10¹³ tokens.</div><ol class=\"gsteps\"><li>$6 \\cdot 7 \\cdot 1.5 = 63$</li><li>$C \\approx 63 \\cdot 10^{10 + 13} = 6.3 \\cdot 10^{24}$ FLOP</li><li>$6.3 \\cdot 10^{24} < 10^{25}$</li><li>Twice as many tokens: $1.26 \\cdot 10^{25} > 10^{25}$</li></ol><div class=\"gans\"><b>Answer:</b> The model is not presumed to have systemic risk, but doubling the training data would cross the threshold.</div>"]},
 {id:"g-dates", n:["Datoer og måneder","Dates and months"],
  f:["Måneder mellom to datoer (samme dag i måneden) $= 12 \\cdot \\Delta\\text{år} + \\Delta\\text{måned}$<br>Ikrafttredelse 1. august 2024", "Months between two dates (same day of month) $= 12 \\cdot \\Delta\\text{years} + \\Delta\\text{months}$<br>Entry into force 1 August 2024"],
  e:["Opprinnelig innfasing etter ikrafttredelse: forbud 6 mnd. → GPAI 12 mnd. → hoveddelen 24 mnd. (2. aug. 2026) → Anneks 1-høyrisiko 36 mnd. Digital Omnibus (2026) utsatte høyrisikokravene til 2. des. 2027 (Anneks 3) og 2. aug. 2028 (Anneks 1).","Original phase-in after entry into force: prohibitions 6 months → GPAI 12 months → main part 24 months (2 Aug 2026) → Annex 1 high risk 36 months. The Digital Omnibus (2026) postponed the high-risk requirements to 2 Dec 2027 (Annex 3) and 2 Aug 2028 (Annex 1)."],
  ex:["<div class=\"gset\">Et selskap tar i bruk et rekrutteringsverktøy (høyrisiko, Anneks 3) og spør 2. aug. 2026 hvor lang tid det har til den utsatte fristen 2. des. 2027.</div><ol class=\"gsteps\"><li>$\\Delta\\text{år} = 2027 - 2026 = 1$, $\\Delta\\text{måned} = 12 - 8 = 4$</li><li>$12 \\cdot 1 + 4 = 16$</li><li>Til sammenligning: 1. aug. 2024 → 2. aug. 2026 ≈ $12 \\cdot 2 = 24$ måneder</li></ol><div class=\"gans\"><b>Svar:</b> Selskapet har 16 måneder på å oppfylle høyrisikokravene.</div>","<div class=\"gset\">A company deploys an Annex 3 high-risk hiring tool and asks on 2 Aug 2026 how long it has until the postponed deadline of 2 Dec 2027.</div><ol class=\"gsteps\"><li>$\\Delta\\text{years} = 2027 - 2026 = 1$, $\\Delta\\text{months} = 12 - 8 = 4$</li><li>$12 \\cdot 1 + 4 = 16$</li><li>For comparison: 1 Aug 2024 → 2 Aug 2026 ≈ $12 \\cdot 2 = 24$ months</li></ol><div class=\"gans\"><b>Answer:</b> The company has 16 months to meet the high-risk requirements.</div>"]}
]}
];
})();
